      desc: "晩餐-Bansun-の最大の特徴は、店名にもある通り「和洋創作」という軸足の自由さにある。一皿ごとに、和食の繊細な出汁使いとフレンチやイタリアンの技法が交差し、予想を心地よく裏切る料理が並ぶ。たとえば、旬の魚介を使った前菜では、和の器に盛られながらもオリーブオイルとハーブが香り、メインの肉料理では赤ワインソースに醤油麹のニュアンスが潜む。こうした融合は、単なる「無国籍」ではなく、素材と調味料の組み合わせが計算され、一つのストーリーとして成立している。久留米という土地柄、博多ほど外食激戦区ではないが、それゆえに地元客が贔屓にする店には独自の哲学と実力が求められる。晩餐-Bansun-は、まさにそうした一軒だ。記念日ディナーや接待、あるいは大切な人との静かな食事に、安心して薦められる創作酒場である。",
