      desc: "創作酒場というと、ともすればコース中心で単品が弱い店もあるが、晩餐-Bansun-では一皿一皿が独立した完成度を持つ。看板となる料理の詳細は訪問時期や仕入れによって変わるが、季節の魚介や九州産の野菜、肉を用いた料理が中心だ。久留米という立地上、筑後川の恵みや有明海の幸、そして筑後平野の農産物が手に入りやすく、それらを和の技法で下処理し、洋の火入れや盛り付けで仕上げるスタイルが多い。たとえば、白身魚のカルパッチョ風に柚子胡椒が効いたソースを合わせる一皿や、鴨肉のローストに山椒とバルサミコを絡めた皿など、和洋の調味料が驚くほど自然に溶け合う。こうした料理は、一品ずつ頼んでシェアするも良し、コース仕立てで流れを楽しむも良し。いずれにしても、久留米の夜をワンランク上の体験にしてくれる皿ばかりだ。",
