      desc: "創作料理の店である以上、酒のラインナップもまた多彩であるべきだ。晩餐-Bansun-では、日本酒は九州を中心に全国の銘柄を揃え、ワインはフランス・イタリアを軸に料理との相性を重視したセレクト。さらに、創作カクテルやクラフトビールも用意されており、和洋問わず料理に寄り添う一杯が見つかる。特に日本酒は、久留米市内にも若波酒造があるように、福岡県南部は酒どころでもある。地元の銘柄を含め、季節ごとに入れ替わるラインナップは、日本酒ファンにも嬉しい。ワインは、魚介に合う白、肉に合う赤を中心に、グラスでも選択肢が豊富。店主やスタッフに好みを伝えれば、料理に合わせてペアリング提案をしてくれることも多い。久留米という土地柄に根ざした、丁寧な酒選びと提案力が光る。酒好きな大人のデートや、接待の二軒目としても重宝する一軒だ。",
