  quoteCite: "マチノワ編集部",
  closing: "久留米で昼から夜まで遊ぶ日に、この店を締めへ置く道のりを描いてみる。15:00、西鉄久留米駅に到着。まずは駅前のカフェで一息つき、16:00から水天宮を散策。筑後川沿いの風景を楽しみながら、久留米市美術館へ立ち寄る（17:00）。美術館を出たら六ツ門商店街を軽く散歩し、18:30には晩餐-Bansun-に到着。予約をしておけば、カウンターまたはテーブル席でゆったりと迎えられる。19:00から料理とペアリングを楽しみ、21:00頃に店を出る。そのまま花畑界隈のバーで一杯、あるいは西鉄久留米駅周辺のホテルへ戻って余韻に浸る。予算は一人あたり5,000〜8,000円程度を見込んでおけば安心だが、酒の種類や料理の内容によって変動するため、事前に予算を伝えておくと良い。予約は必須ではないが、週末や記念日は混雑が予想されるため、電話またはGoogleマップ経由で予約しておくのが無難だ。久留米という街を「通過点」にせず、夜まで楽しむ。その起点として、晩餐-Bansun-は頼もしい存在である。",
