  sideArticles: [],
  quote: "Kitchen Kenは、草牟田という生活エリアで昼と夜の二つの顔を持つ一軒。昼はハンバーグや黒豚カツカレーといった洋食をしっかり食べさせ、夜はレンガ調の店内で洋酒やダーツを楽しめるダイニングバーになる。鹿児島で「がっつり食べたい」「遅い時間まで気楽にゆっくり飲みたい」と思ったとき、思い出したいお店です。",
  quoteCite: "マチノワ編集部",
  closing: "草牟田でKitchen Kenを使うなら、昼の洋食から知るのが分かりやすい。最初は昼の洋食から入るのが分かりやすい。看板のハンバーグや、鹿児島らしい黒豚カツカレーをセットで頼めば、ご飯・スープ・デザートまで付いて一皿で満足できる。昼にしっかり食べたい日の食事処として、まず頼りになる一軒だ。仕事帰りや夜に過ごしたいなら、レンガ調の店内で洋酒を傾けたり、ダーツを楽しんだりできるダイニングバーとしての顔を狙うといい。遅い時間まで開いているため、食事のあとに腰を据えたい日や、二軒目として立ち寄りたい日にも合わせやすい。一人なら昼食として気軽に、少人数なら夜にテーブルを囲んで――用途を選ばず使えるのがこの店の強みだ。所要時間は昼の食事で1時間ほど、夜にゆっくりするなら2時間ほどを見ておくと落ち着く。立地は草牟田の生活エリアで、市電電停からは距離があるため車での来店がしやすい。営業時間・定休日・メニュー・料金は時期や状況で変わる可能性があるため、訪れる前に電話 099-227-7691 もしくは公式情報での確認を勧めたい。鹿児島で昼も夜も使える洋食ダイニングを探しているなら、Kitchen Kenは草牟田で頼れる一軒になる。",
