      desc: "すすきの浪花亭の核にあるのは、1962年の創業以来受け継がれてきた会席料理だ。半世紀を超える歴史の中で磨かれてきたのは、北海道という土地の恵みを、いかにおいしく食卓へ届けるかという仕事である。海に囲まれ、山や畑の幸にも恵まれた北海道は、四季ごとに表情を変える食材の宝庫だ。浪花亭はその旬を見極め、先付から椀物、造り、焼き物、揚げ物と、一品ずつ流れるように仕立てた会席で味わわせてくれる。会席という形式の良さは、料理が運ばれる順番そのものに緩急があり、食事の時間に物語が生まれることにある。札幌の夜にあって、ただ腹を満たすのではなく、季節を一皿ずつたどっていく食事ができる。慌ただしい日常から少し背筋を伸ばして食卓に向かいたい夜に、こうした一軒があるのは心強い。料理の内容は季節や仕入れで変わるため、その日の献立は予約のときに尋ねておくと、当日の楽しみがふくらむ。何度訪れても、その季節ごとの一皿に出会えるのが、長く続く会席の店ならではの良さだ。",
