  sideArticles: [],
  quote: "Ristorante t.v.bは、祇園の町家で季節のイタリアンを味わえる一軒。その日の素材をワゴンから選び、前菜からメインまでをコースでゆっくり楽しむ時間は、京都での特別な食事にふさわしい。記念日や大切な人との食事に、八坂神社や円山公園の散策とあわせて――そんな京都の一日を思い描いたとき、思い出したいお店です。",
  quoteCite: "マチノワ編集部",
  closing: "祇園でRistorante t.v.bに向き合うなら、その日の素材から入るのがいい。最初はその日の素材をワゴンで見せてもらい、おすすめを尋ねながらコースを組み立てるのが分かりやすい。実物を見て選べるので、京都の四季がそのまま皿に映るのを楽しめる。記念日やデートで訪れるなら、町家を改装した落ち着いた空間が特別な日の食事によく合う。前菜からメインまで会話をしながらゆっくり進められるので、二人の時間を大切にしたい夜にちょうどいい。ひとりや少人数なら、静かに料理と向き合える環境を生かして、自分へのご褒美の食事として使うのもいい。所要時間は、コースを通して味わうなら1時間半から2時間ほどを見ておくと落ち着く。立地は京阪の祇園四条駅から徒歩7分ほどで、八坂神社や円山公園、知恩院の散策と前後につなげやすい。営業はランチが正午から、ディナーが18時からの二部制で、定休は日曜と不定の平日。価格帯はランチとディナーで異なり、コース内容や料金、時間は時期によって変わる可能性があるため、訪れる前に電話075-525-7070または公式情報での確認を勧めたい。京都で、食事そのものを主役にした一日を過ごしたいなら、Ristorante t.v.bは祇園で頼れる一軒になる。",
