      purpose: "誰とどう使えるか知りたい人へ",
      desc: "美奈吉は、使い方の幅が広い店だ。広いお座敷とコースを軸に、家族三世代の集まりや子ども連れの食事、年配の方を囲む席まで、畳の上でゆっくり過ごせる。記念日やお祝いには小さな寿司ケーキのサプライズを頼めるし、法事や会合のような改まった席にも落ち着いて使える。一方で、店に行くことだけが利用法ではない。美奈吉は出前と宅配にも応じていて、野里・上野口・舟田・大池・常盤町といった大和田エリアへ届けてくれる。大皿盛りや個別盛り、パック盛り、幕の内やオードブルも相談でき、家での集まりや法事の仕出しにも使える。出前館とUber Eatsにも対応しているので、家飲みの一皿を頼むこともできる。お店で囲んでも、家に届けてもらっても成立する――この懐の深さが、地元で半世紀あまり続いてきた理由なのだろう。予約優先の営業で、仕出しや座敷の予約が入っている日は店内営業を休むこともあるため、来店前に一度電話を入れておくと行き違いがない。",
