  quote: "麺屋 工藤 藤井寺店は、古市古墳群の街・野中で豚スープのラーメンを出す一軒。河内永和の本店が鶏なら、こちらは豚。清湯からガリ豚やピリ辛豚まで気分で選べて、定食やサイドも充実している。藤井寺で気軽に通える一杯を探しているなら、思い出したいお店です。",
  quoteCite: "マチノワ編集部",
  closing: "藤井寺・野中で麺屋 工藤に立ち寄るなら、看板の一杯から入るのがいい。最初は看板格の豚清湯ラーメンを頼んで、澄んだスープに背脂が重なるこの店の軸を確かめるのが分かりやすい。醤油と塩から選べるので、迷ったら醤油でいい。こってり食べたい日は、豚骨系のガリ豚やニラ豚、刺激がほしければピリ辛豚へ進むと、同じ豚スープの別の顔に出会える。しっかり食べたいランチなら、半チャンセットのような定食や、焼きめし・餃子を合わせて腹ごしらえするのがちょうどいい。一人なら手早く一杯を、家族や友人となら違う種類を頼んで少しずつ味を見せ合うのも楽しい。駅からは少し距離があるので、車で訪ねるなら4台分の駐車場が頼りになる。古市古墳群の散策や藤井寺めぐりと組み合わせ、歩いたあとの一杯として立ち寄る使い方も合う。昼は11時から14時半、夜は17時から21時半の二部制で、定休は木曜とそのほか不定休。営業時間や定休日、料金は変わる可能性があるので、出かける前に072-937-7277へ電話で確認しておくと確実だ。藤井寺で気軽に通える豚スープの一杯を探しているなら、麺屋 工藤 藤井寺店は頼れる一軒になる。",
