  lede: "近鉄奈良駅から興福寺や奈良公園へ向かう人波の少し外、西城戸町の落ち着いた通りに梁山泊はある。観光客でにぎわう三条通から一本入った場所で、地元の家族が祝い事や法事、節目の食事に使ってきた日本料理の店だ。古都奈良で半世紀以上のれんを守り、旬の食材を生かした会席と七十種を超える一品料理、奈良県産を含む各地の銘酒で知られている。観光のついでに立ち寄る一軒というより、家族の大切な一日を任せられる場所として根を張ってきた。のどぐろの塩焼きや夏の鱧、岩塩で焼くヤマトポークといった季節の皿を、座敷でも掘りごたつでもカウンターでも味わえる懐の深さがある。誰とどんな日に訪ねると気持ちよく過ごせるのか、料理から空間、奈良歩きとの組み合わせまで順にたどっていく。",
