      purpose: "この店の核となる料理を知りたい人へ",
      desc: "梁山泊の軸にあるのは、季節の食材を一皿ずつ組み立てる会席料理だ。会席は段階で用意され、先付から椀物、造り、焼き物、食事まで、その時季の奈良や各地の素材を順に味わえる構成になっている。会席だけでなく、七十種を超えるという一品料理の幅広さもこの店の持ち味で、刺身の盛り合わせから焼き物、鍋まで、その日の人数や気分に合わせて単品で頼める自由度がある。コースで通しても、数品をみつくろって酒と合わせても成立するのは、和食の店として地力があるからだ。昼には点心の御膳も用意され、夜の会席とはまた違った軽やかな使い方ができる。きっちりとした会席で節目を祝うのか、一品料理をつまみながら酒を傾けるのか――同じ店でその両方が選べるところに、長く続いてきた店ならではの幅を感じる。何を食べたいか決めかねていても、その日の品書きを眺めるところから始められるのがいい。",
