      desc: "梁山泊が西城戸町でのれんを掲げて、すでに半世紀あまりになる。奈良の街で世代を超えて使われてきた店で、初めての顔合わせや七五三、お食い初め、そして法要まで、人生の節目に集まる場として選ばれ続けてきた。観光地の中心にありながら、客の多くが地元の家族連れというのは、こうした祝い事の積み重ねが信頼として残っているからだろう。お食い初めには祝い鯛を添えた膳を、慶弔の集まりにはそれぞれの趣旨に合わせた料理を用意するなど、家ごとの事情にこたえてきた経験がうかがえる。仕出しや弁当の対応もあり、店で食べるだけでなく持ち帰って家で囲むかたちも選べる。流行を追いかけるのではなく、その家の大切な一日を預かることを続けてきた――そういう積み重ねが、奈良で会席といえば名前が挙がる一軒にしている。背伸びをしに行く店というより、節目のたびに帰ってくる店として付き合える落ち着きがある。",
