      purpose: "具体的な名物と酒の中身を知りたい人へ",
      desc: "具体的に名前が挙がる皿も多い。脂ののったのどぐろの塩焼きは、焼き物の看板といっていい一皿だ。夏になると鱧が並び、鱧寿司や鱧鍋、てっちりといった関西らしい献立で季節を知らせてくれる。県産ブランド豚のヤマトポークを岩塩で焼く一品や、鰻を蒸し上げた飯蒸しなど、奈良ならではの素材とひと手間をかけた仕事が組み合わさる。こうした皿に合わせたいのが酒で、奈良県産を含む日本各地の銘酒が常に用意されている。清酒発祥の地のひとつとされる奈良で、和食をつまみながら地の酒を傾けるのは、この店だからこそ似合う時間の使い方だ。会席の流れに沿って一杯ずつ替えるのも、気になる一品に合わせて選ぶのも自由がきく。季節で品書きは入れ替わるので、その日に何が出るかは足を運んでからの楽しみになる。メニューや価格は時期で動くので、目当ての料理があるなら電話や公式の案内で確かめてから出かけると確実だ。",
