      desc: "焼肉タカ屋が店の名前にまで掲げているのが、自家製の手作りダレだ。市販のタレを使わず、店で仕込んだ秘伝のダレで肉を食べてもらう――その一点に、この店の立ち位置がはっきり出ている。タレは肉のうまみを引き出す脇役でありながら、店ごとの個性がもっとも分かれる部分でもある。タカ屋はそこを自前で作り込むことで、ほかでは口にできない味の組み合わせを用意している。あわせて売りにしているのが肉の鮮度と質で、タレと肉のどちらかに偏るのではなく、両輪で焼肉の満足度を組み立てようとしている姿勢が伝わる。公式の案内では部位や産地までは細かく明かされていないので、その日いちばんのおすすめは席についてから店の人に尋ねるのが早い。仕切りのある席で、自分のペースで焼いて、タレにくぐらせてほおばる――焼肉という食べ方そのものを、落ち着いて楽しめる店だ。何を頼むか迷ったら、定番の部位をタレで試してみると、この店の方向性がつかめる。",
