      purpose: "専門店ならではの食べ方を求める人へ",
      desc: "なかざきが掲げているのは、宮崎で初めて牛かつ一本に絞った専門店という看板だ。肉を揚げる、その一品を主役に据えているからこそ、食べ方の作り込みに店の個性が出る。卓上には三種の薬味が並ぶ。粒の立った岩塩、つんと抜けるわさび醤油、そして玉ねぎを土台にした秘伝のソースだ。同じ一切れでも、塩で赤身の甘みを引き出すか、わさび醤油で後味を締めるか、ソースでこってり寄せるかで、口に運ぶたびに表情が変わる。一枚の定食を端から薬味を替えて食べていくと、途中で飽きが来ない。揚げ加減を石板で調整できることと合わせて、自分で味を組み立てる余地が大きいのが、専門店ならではの面白さだ。順番に迷ったら、まずは岩塩で素材を確かめ、次にわさび醤油、最後に秘伝ソースへと濃さを上げていくと、味の輪郭をたどりやすい。薬味の構成やメニューは変わることがあるので、気になる品があれば来店時に確かめておくといい。",
