      area: "熊本市南区薄場",
      purpose: "誰とどう過ごせるか知りたい人へ",
      desc: "ピノッキオは、こぢんまりとした一軒のような構えの店だ。席数は二十ほどで、テーブル席のほかにカウンターもあり、一人で来て料理に向き合うのにも、二人三人で囲むのにも収まりがいい。小さな子ども向けの椅子も用意されているので、家族での昼食にも使いやすい。店が大きくないぶん、つくり手との距離が近く、料理が運ばれてくるたびにその日のひと皿を味わう時間が生まれる。昼は近所の人や常連でにぎわい、午後一時を過ぎると潮が引くように落ち着くので、静かに食事をしたい人は時間をずらすのもいい。気取らない雰囲気だから、特別な日でなくても入りやすい。テーブルとカウンターが選べることで、その日の人数や気分に合った席で過ごせるのもありがたい。一人のランチから、家族や友人との食事まで、用途を選ばず使える懐の広さがこの店にはある。",
