  sideArticles: [],
  quote: "ピノッキオは、イタリアで腕を磨いた店主が薄場の一角で続ける小さなイタリア料理店。手打ちのパスタと地の野菜を、気負わない値段で出し続けている。本場の味を構えず味わいたくなった日に、熊本市南区で思い出したい一軒——薄場まで足を運ぶ値打ちが、ちゃんとある店です。",
  quoteCite: "マチノワ編集部",
  closing: "本場仕込みの一皿を昼に狙うなら、混み合う時間を少し外して動くと過ごしやすい。最寄りのJR西熊本駅から歩くか車で向かうことになるが、店構えが控えめなので、熊本銀行の薄場支店を目印に進むと見つけやすい。最初の一回は、まず二種類あるランチコースのどちらかを選び、前菜から手打ちパスタ、デザートと飲み物までをひと続きで味わうのがこの店の入口になる。本格的なイタリア料理がこの値段で、という地元の評判を、自分の舌で確かめる時間だ。家族で訪ねるなら、子ども用の椅子もあるので昼のうちにゆっくり過ごすのがいい。気の置けない相手とであれば、夜の二時間飲み放題付きコースを二名から予約して、アラカルトも交えながら腰を据えるのも楽しい。所要は、昼のコースなら一時間ほど、夜にじっくりなら二時間ほど見ておけば足りる。予算は昼と夜で開きがあるので、その日の目的に合わせて選ぶといい。月曜が休みにあたるので、出かける前に096-358-3332へ電話を入れ、営業と席を確かめておくと当日が落ち着く。薄場の静かな通りで、アオスタ仕込みの料理にゆっくり向き合ってみてほしい。",
