      desc: "二郎系を語るうえで外せないのが、注文時の『コール』だ。イエローでも、配膳の前に野菜・ニンニク・アブラの量を選べる仕組みになっている。そのまま頼めば標準だが、『マシ』『マシマシ』と伝えれば、もやしの山がさらに高くなり、脂とニンニクの効きも増していく。この無料トッピングを自分好みに組み立てられるのが二郎系に通う楽しみのひとつであり、イエローでも同じ流儀が生きている。初回は加減が分からず盛りすぎてしまうこともあるので、最初は標準か、野菜だけ少し増やすくらいから試すと、自分の適量が見えてくる。常連はその日の腹具合でコールを変え、同じ一杯でも毎回少し違う表情を引き出していく。決まった正解があるわけではなく、自分の食べ方を育てていける――この自由度が、一度きりで終わらせず通いたくなる理由になっている。慣れてきたら少しずつマシの幅を広げていくのも、この店との付き合い方だ。",
