  lede: "こあの助という店名には、タイ語で台所を意味する『こあ』と、日本語の『助ける』が重ねられている。京都市左京区、京都大学にほど近い百万遍から田中門前町へ抜けるあたりに店を構えるタイカレーの一軒だ。東大路通のひと筋内側に入ると、ビルの二階へ上がる小さな入口が見つかる。グリーンカレーやイエローカレー、ガパオライスといったタイ料理に、豚納豆丼のような創作どんぶりが並ぶのがこの店の持ち味で、タイと日本の食卓が一枚の品書きに同居している。学生の昼食にも、近隣で働く人の夜の一皿にも応えてきた、左京区の暮らしに溶け込んだ店だ。その魅力を、編集部目線で五つの視点からたどっていく。",
