      purpose: "実際に行くときの道順と使い方を知りたい人へ",
      desc: "麺屋野条があるのは、兵庫県西宮市門戸荘。最寄りは阪急今津線の門戸厄神駅で、改札からは歩いて二分ほどと、迷いようのない近さだ。門戸厄神駅の名は、すぐ近くに門戸厄神東光寺があることに由来する。厄除けで知られるこの寺は参拝に訪れる人も多く、お参りの行き帰りに駅前で一杯、という組み立てもできる。今津線は西宮北口で神戸線・宝塚線に乗り換えられるため、宝塚や西宮北口方面からのアクセスも良い。駅前には商店や飲食店が並び、買い物や用事のついでに立ち寄りやすいのも、この立地ならではの強みだ。営業時間や定休日は変わることがあるため、来店前に最新の情報を確かめておきたい。オープンしたばかりの店なので、行列や売り切れの可能性も頭に入れておくと、足を運んだ日に空振りせずに済む。門戸厄神での半日に、鶏白湯の一杯を一つの目的地として組み込んでみてほしい。",
