  titleHTML: "鮨寄宮たいら、<br>那覇・寄宮の<em>五席の鮨。</em>",
  subtitle: "完全予約制の鮨店、那覇市寄宮で味わうおまかせのカウンター",
  lede: "那覇の中心部から国際通りの賑わいを少し離れ、南へ下っていくと、寄宮(よせみや)という生活の街に行き着く。県道46号線沿いに住宅と商店が混ざり合うこの一帯は、観光客の流れからは一歩外れた、地元の人の暮らしが続く場所だ。その寄宮二丁目に、カウンター五席だけの小さな鮨屋がある。鮨寄宮たいらは、大将がひとりで握り、完全予約制で客を迎える店。扉を開ければ、目の前には握り台と、たいらと記された木の看板。観光地の華やかさではなく、予約した人だけが座れる五席の静けさが、この店の時間を作っている。接待や記念日、大切な人との食事に選ばれてきたのには理由がある。那覇で、落ち着いて鮨と向き合いたい夜に思い出したい一軒を、編集部の視点で見ていきたい。",
  date: "2026-06-09",
