      desc: "鮨寄宮たいらの核は、大将がひとりで握るおまかせのコースにある。好きなものを一品ずつつまむ店ではなく、先付けから始まり、お造り、火を入れた逸品、握り、お椀、そしてデザートまで、ひとつの流れとして組み立てられた構成を、目の前で順に出していく形だ。握りはコースの中心に据えられ、仕入れによって内容が変わるため、同じ日が二度とないのがおまかせの面白さでもある。カウンターは五席だけ。大将の手元がそのまま見える距離で、シャリを握り、ネタをのせ、ひと皿ずつ差し出される様子を眺めながら食べ進める。会話のテンポも、握りが出てくる間合いも、大将ひとりが差配しているから、店全体がひとつのリズムで動いている。何を食べるか迷う必要はなく、その日のおまかせに身を委ねればいい。握り台の向こうで一貫ずつ仕上げられていく所作を間近で見られるのも、五席という近さがあってこそだ。コースの品数や内容は時期や仕入れで動くので、気になる人は予約のときに尋ねておくと、当日の流れがつかみやすい。アラカルトで構える気軽さよりも、出される順に身を任せる楽しさを味わう店だと考えておくといい。",
