      cuisine: "店の個性",
      area: "那覇市寄宮",
      purpose: "通いたくなる理由、店の使い方を知りたい人へ",
      desc: "通いたくなる理由を挙げるなら、まずこの五席という規模だ。カウンターだけの小さな空間に、大将がひとり。予約をした客だけが順に席に着くため、店の中はいつも顔ぶれの知れた静けさに包まれている。大人数でにぎわう鮨屋とは、過ごし方がまるで違う。少人数で訪れれば、ほとんど貸し切りのような時間になり、二人や数人で卓を囲めば、まわりを気にせず会話と握りに集中できる。実際、この店は気の置けない相手との食事会や、貸し切りでの集まりにも使われてきた。大将と言葉を交わしながら、その日のネタの話を聞き、握りを待つ――カウンター越しのやり取りそのものが、この店ならではの楽しみになっている。五席しかないということは、裏を返せば一人ひとりに手が届く距離で迎えられるということだ。だからこそ、特別な日や、静かに向き合いたい相手との時間に選ばれてきた。予約が前提の店なので、思い立ったら早めに席を押さえておきたい。",
