      purpose: "蕎麦そのものの出来を目当てに訪ねたい人へ",
      desc: "この店の軸は、店主が毎日打つ蕎麦にある。配合はそば粉八に小麦二の二八で、上質なそば粉を使い、その日の気温や湿度を見ながら水加減を決めてベストの状態に仕上げていく。打ち上がるのは細めの麺で、口当たりがよく、出汁とのなじみがいい。茹で時間にも気を配り、ゆで上げの一瞬を逃さずに供する姿勢が、一杯ごとの安定した食感につながっている。つゆの土台になるかえしは長年にわたって継ぎ足されてきたもので、甘さと辛さのバランスが整い、温かい蕎麦でも冷たい蕎麦でもぶれない。蕎麦は気候と手仕事に左右されやすい食べ物だからこそ、毎朝その日の条件に合わせて打ち直すという手間が、そのまま味の差になって表れる。手繰った一本目で、ああ今日もきちんと打たれているな、と分かる。蕎麦の出来そのものを目当てに足を運んでも、応えてくれる店だ。",
