      desc: "店があるのは小倉南区日の出町一丁目、小倉競馬場にほど近い閑静な住宅街の一角だ。北九州モノレールの守恒駅から歩いて五分ほどと、公共交通でも訪ねやすい立地にある。車で向かう人には駐車場が三台分用意されているので、モノレール沿線の外から来るときも安心だ。観光の動線からは外れた生活の街なので、ふらりと通りかかって入るというより、目的地として足を向ける店になる。競馬開催日に小倉競馬場とあわせて立ち寄る、買い物や用事のついでに昼の一杯を手繰る、仕事帰りに守恒で降りて夜の蕎麦呑みに腰を据える――守恒という街の過ごし方に、自然と組み込める一軒だ。守恒駅周辺は生活感のある落ち着いたエリアで、駅から店までの道のりも静かだから、訪ねること自体が小さな散歩になる。昼の営業は午後の早い時間で区切られ、夜は夕方から始まるため、狙う時間帯を決めてから向かうと取りこぼしがない。昼と夜で営業時間が分かれ、定休日もあるため、訪れる前に当日の営業を確かめてから動くと無駄がない。住宅街の中の一軒家を目指して歩く、その数分そのものが、この店へ向かう小さな助走になる。",
