      desc: "道後ハイボール酒場という名前が、この店のやりたいことを言い切っている。湯あがりに飲みたくなる一杯として真っ先に浮かぶのが、よく冷えたハイボールだ。温泉でじんわり温まった体に、炭酸の刺激とウイスキーの香りがすっと染みていく――その心地よさを、わざわざ説明する必要もないほど店名がまっすぐに掲げている。道後という温泉街で、湯あがりの一杯を看板に据えた店は意外と多くない。腰を据えた食事の前の景気づけにも、観光をひと通り終えたあとの仕上げにも、ハイボールという軽やかな酒はちょうどいい。難しい作法も気構えもいらず、まずは一杯、と気軽に頼める。観光地の夜に、肩の力を抜いて立ち寄れる飲み屋があること自体が、旅の安心感につながる。湯けむりの余韻を肴にグラスを傾ける、それがこの店の真ん中にある時間だ。これ、地味に効く。",
