      desc: "この店の真ん中にあるのは、蕎麦そのものへのこだわりだ。北海道産の蕎麦粉を石臼で挽き、香りの立つ一枚に仕立てている。蕎麦は粉の鮮度と挽き方で表情が大きく変わるものだが、ここはその工程に手をかけているからこそ、出てくる一枚に芯がある。手繰ったときにまず鼻へ抜ける香り、噛んだときに返ってくるコシ、そして喉ごしと、ひと口の中にいくつもの段階があり、蕎麦を味わうという行為そのものが面白くなる。冷たいせいろで蕎麦本来の風味を確かめるもよし、温かい一杯で出汁とともに手繰るもよし、蕎麦を主役として正面から楽しめる一軒だ。久留米という、ラーメンや焼き鳥の印象が先に立ちがちな土地にあって、蕎麦を目的に足を向けられる店があることの意味は大きい。蕎麦好きが少し遠回りしてでも訪ねたくなる、その理由が一枚の蕎麦に詰まっている。これ、手繰ってみると舌で分かる。",
