      desc: "通いたくなる理由を挙げるなら、昼の時間だけ静かに開くという潔さがある。営業は十一時から十五時まで、ラストオーダーは十四時半。夜はやらず、昼の蕎麦に専念する構えだ。だからこそ、昼にしっかり蕎麦と向き合いたい日に狙いを定めやすい。さらにこの店には中庭があり、席から庭を眺めながら蕎麦を待つ時間がある。慌ただしく掻き込むのではなく、庭の緑に目をやりながらひと息つき、運ばれてきた一枚をゆっくり手繰る――その流れ自体が、ここで過ごす時間の質を上げてくれる。田んぼ道の先に佇む一軒家という立地もあって、店に着いた瞬間から日常の速度がふっと緩む。人気店ゆえ昼どきは待ちが出ることもあるが、その待ち時間さえ庭を眺めて過ごせるのだから悪くない。慌てず、昼の数時間をこの一軒に充てる――そういう使い方が似合う店だ。営業時間や定休日は変わることがあるため、来店前に最新の営業を確かめておきたい。",
