  quoteCite: "マチノワ編集部",
  closing: "学校前駅から田園の道を数分、田んぼ道の先に店があると分かっていれば、この一軒の使い方はぐっと描きやすくなる。営業は昼だけなので、まずは昼の時間に狙いを定めるのが基本だ。一人で訪ねるなら、中庭を眺めながら冷たいせいろで蕎麦そのものの香りを確かめるのがいい。二人や家族で来るなら、せいろと鴨の蕎麦を頼み分けて、温と冷の両方を味わってみるのも楽しい。年配の方を連れての昼の会食にも、きちんとした構えのこの店は向いている。久留米の市街地で用事を済ませた帰りに少し足を延ばす、あるいはこの一軒を昼の目的地に据えて宮ノ陣の田園をのんびり巡る――どちらの組み立てでも収まりがいい。人気店ゆえ昼どきは待ちが出ることもあるので、時間に余裕を持って向かうと安心だ。予算感や所要時間はその日の頼み方しだいだが、蕎麦をゆっくり味わうなら、昼の数時間をこの店に充てるつもりで動きたい。昼だけの営業で火曜と水曜が定休のため、行く日が決まったら当日の営業を確かめておくと確実だ。田園の風景の中で、蕎麦を主役に静かな昼を過ごす。久留米でそんな時間を探している人に、ちょうどいい一軒だ。",
