      area: "白石区北郷",
      purpose: "炭火で焼いた串そのものを目当てに訪ねたい人へ",
      desc: "店の名前が示す通り、ここの軸は炭火で焼く串にある。ガスではなく炭の熱で焼くと、表面は香ばしく色づき、中はふっくらと火が通る。脂が炭に落ちて立ちのぼる煙が串にまとわりつき、あの独特の香りが生まれる。一の屋では、その一本一本を焼き手が炭の前で仕上げていく。鶏のさまざまな部位を素材にした定番の串が並び、プチトマトを巻いた変わり串のような、つい箸が伸びる一品も焼かれている。炭火焼きは火加減と焼き時間の見極めがそのまま味に出る調理で、同じ串でも焼き手の手元で仕上がりが変わってくる。だからこそ、目の前で焼かれた串を熱いうちに頬張るのが、この店のいちばんの楽しみ方になる。塩で素材の味を確かめるもよし、たれで香ばしさを重ねるもよし。炭の香りをまとった串は、ビールでもハイボールでも日本酒でも、その日の一杯をぐっと進ませてくれる。炭火で焼くという手間のかかるやり方を、看板に掲げてやり続けているところに、この店の構えが表れている。まずは焼きたての一本から、この店の輪郭をつかんでほしい。",
