      rank: "POINT 04",
      rankNum: 4,
      name: "カウンターのある、町場の焼き鳥屋らしい距離感",
      cuisine: "空間・客層",
      area: "白石区北郷",
      purpose: "誰と、どんな気分で行く店かを知りたい人へ",
      desc: "店の構えは、気取らない町場の焼き鳥屋そのものだ。引き戸を開けると、炭の前で串が焼かれる気配と、テーブル席のある落ち着いた店内が迎えてくれる。観光客でにぎわう繁華街の店とは違い、近所の常連や家族連れが日常的に通う、生活圏の一軒という空気が流れている。一人で来て黙々と串をつまみながら一杯やるのにも、気のおけない仲間と囲むのにも、家族で夕飯がてら立ち寄るのにも、肩肘の張らない距離感がちょうどいい。炭の前で串が焼かれていく様子を眺めながら待つ時間も、焼き鳥屋ならではの楽しみだ。近所で働く人や暮らす人にとっては、特別な日でなくても気軽にのぞける、生活の延長線上にある店だろう。夜だけの営業なので、店内には一日の終わりにほっと一息つく大人の時間が流れている。混み合う時間帯もあるから、人数がまとまるときや確実に座りたいときは、電話を一本入れておくと安心だ。きっちり呑む夜にも、さっと一杯で切り上げる夜にも応えてくれる、ふところの広さがある。誰と来ても収まりがいいから、用途を選ばず使えるのがありがたい。",
