      desc: "具体的な品書きを覗いてみる。柱になるのは焼き魚定食で、その日の魚を主役に据えた、定食店の王道だ。揚げ物が食べたい日にはミックスフライ定食、しっかり肉で力をつけたい日には白老牛ハンバーグ定食と、選択肢は気分に正直に応えてくれる。変化球として手が伸びるのが生ラムジンギスカン定食で、羊肉の香りとタレの、ごはんとの相性は、一度知ると次も頼みたくなる。北海道の食堂らしく、ザンギ（北海道風の鶏唐揚げ）を目当てにする声も多い。どれを選んでも前述のドリンクとデザートが付くので、一食の満足度は主菜だけでは決まらない。重い・軽い、和・洋を日替わりで組み合わせられるから、近隣で働く人が週に何度も通えるのだろう。お目当ての一皿があるなら、その日に用意があるか事前に店へ尋ねておくと安心だ。",
