      desc: "信ちゃんママがあるのは、北郷三条のビルの二階だ。一階の路面店とは違い、階段を上った先にある分、初めてだと少し奥まって感じるかもしれない。だが、その一段上がった空間が、昼の往来からほんの少し離れた落ち着きを生んでいる。営業は平日も土曜も昼の時間帯に限られ、夜は開かない。だからここは、ゆっくり夜を飲み明かす店ではなく、昼の一食を真ん中に据える店だ。一人で黙々とごはんを進めるのにちょうどよく、近所の人が連れ立って昼を囲むのにも向く。ママとの短い言葉のやり取りが、家の食卓に戻ったような感覚を残してくれる。かしこまった会食には不向きだが、気負わず昼を食べたい日には、この二階がしっくりくる。お子さま連れや年配の方の利用については、階段のことも含めて、来店前に一度問い合わせておくとよい。",
