      desc: "アクセスは、JR函館本線の白石駅北口から歩いて十三分ほど。車での来店なら、北郷通など幹線道路からも入りやすい立地だ。白石区北郷は、観光名所が連なるエリアというより、地元の人が日々使う生活のまちで、だからこそ、ここを目当てに足を運ぶと、等身大の札幌が見えてくる。昼に信ちゃんママで定食を済ませたあとは、白石や菊水あたりから地下鉄で大通や札幌駅へ抜けて、午後の買い物や観光に切り替えるのも組みやすい。逆に、白石区を歩く一日の昼食地点として、この店を据えるのも収まりがいい。夜は営業しないぶん、午前から昼にかけての行動の中に組み込むのが現実的だ。札幌の中心部だけを巡る旅では出会えない、生活圏のなかの昼の一食を挟みたい人に、ちょうどいい寄り道になる。曜日や時間帯で営業が変わることもあるので、出かける前に確認しておくと足を運びやすい。",
