  lede: "姫路の中心から播但線で数駅、北へ上がった砥堀のあたりは、観光の喧騒からは少し離れた、姫路で暮らす人たちの生活のまちだ。幹線道路沿いに店が点在し、買い物や通勤の動線が静かに流れていく――そんな一角に、麺家 本倉はある。東京の名店で腕を磨いた店主が、地元の姫路へ戻って二〇二二年に構えた一軒で、掲げるのは鶏豚魚介の濃厚つけ麺と、澄んだ鶏清湯や煮干しのラーメン。こってりと淡麗、相反する方向性の一杯を一つの暖簾の下で味わえるのが、この店の面白さだ。昼も夜も営業し、麺がなくなれば静かに店じまいする、その実直な構えにも作り手の人柄がにじむ。姫路で一杯を探すとき、城下の名店だけでなく、砥堀のこの店を覚えておく価値は十分にある。ここからは、本倉という一軒の輪郭を、味と立地の両面からたどっていく。",
