      desc: "麺家 本倉の顔は、鶏と豚、そして魚介を一杯に束ねた濃厚つけ麺だ。鶏ガラや丸鶏、もみじといった鶏の旨みを土台に、豚の厚みを重ね、三日ほどかけてじっくりと炊き上げる。仕上げに節や煮干しの魚介を効かせることで、こってりとしながらも後口に旨みの輪郭が残る、いわゆる鶏豚魚介の系統に仕上げている。太めの麺はつけ汁をしっかりと持ち上げ、海苔やメンマ、低温調理らしいしっとりした鶏チャーシューが添えられる。一口目の濃さに驚いても、白髪ねぎの清涼感が舌をいったんリセットしてくれるから、最後まで重さに飽きずに手繰れる。締めにスープ割りを頼めば、魚介の余韻を確かめながら一杯を見送れる。姫路の北、砥堀という生活圏で、これだけ手間をかけた一杯に出会えること自体が、この店を目指す理由になる。仕込みの都合で麺は売り切れ次第終了となるため、つけ麺狙いなら時間に余裕を持って向かいたい。",
