  titleHTML: "小料理 <em>木下、</em><br>大久保の夜の止まり木。",
  subtitle: "大久保駅前の小料理店で過ごす、気取らない和の夜",
  lede: "明石市の東の玄関口、JRの大久保駅。三ノ宮・神戸方面へも、西明石・姫路方面へも出やすいこの駅の周りは、商業施設と住宅地が混じり合う、暮らしの匂いがする街だ。通勤で毎日通り過ぎる人も多いだろう駅前に、小料理 木下はある。北口を出て歩いて三分、駅前の落ち着いた通りに面していて、仕事帰りや週末の夜に、ふらりと暖簾をくぐれる距離感がいい。小料理という業態は、その日の気分で一品ずつ頼み、カウンター越しに和食と向き合う、大人のための時間だ。特別な日のためというより、ふだんの夜を少しだけ豊かにしてくれる種類の店だと思う。ここでは木下という一軒を、大久保の街の中に置きながら、いくつかの角度から見ていきたい。",
