      desc: "木下は、グルメサイトでは小料理・日本料理として紹介されている一軒だ。小料理という言葉には、決まったコースを大勢で囲むのとは違う、その日の気分で一品ずつ頼んでいく和食の自由さがある。カウンターに腰を下ろし、品書きを眺めながら、今日は何にしようかと考える。その時間こそが、小料理屋の楽しみどころだと思う。何を出すかは季節や仕入れで変わるのが和食の常で、訪れるたびに違う表情を見せてくれるのも、こうした店ならではの良さだ。春には春の、冬には冬の食材が品書きに並ぶから、季節が変わるたびに足を運ぶ理由が生まれる。チェーンの居酒屋とは違い、店の手が一皿ごとに入る。だからこそ、頼んだ料理が運ばれてくるまでの少しの間も、どこか心地いい。お酒を片手に、次は何を頼もうかと品書きを眺める——その往復そのものが、小料理屋という時間の中身なのだと思う。具体的な品書きは時期で動くので、気になる料理があれば、来店前に電話で尋ねておくと話が早い。大久保で和食を一品ずつ、自分のペースで——そんな夜を探しているなら、まず候補に入れておきたい店だ。",
