      purpose: "この店の核がどこにあるかを知りたい人へ",
      desc: "ジョージレストランの料理は、戦後のアメリカ統治下に根を持つ沖縄の洋食だ。Aサインとは、米軍の衛生基準を満たした飲食店だけに与えられた営業許可のことで、頭文字のAは「Approved（許可済）」を表す。その厳しい基準をくぐり抜けた時代から、この店はステーキやハンバーグといった洋皿と、メキシコ由来のタコスを並べてきた。とりわけタコスは、創業以来変わらぬ製法で生地から手作りされているのが特徴で、この一品にこの店の来歴が凝縮している。沖縄の食堂文化のなかでも、洋食とタコスを同じ皿の地平で出す店は、米軍とともに育ったこの土地ならではのものだ。デリバリーやテークアウトも数十年来続けてきたといい、地域の食卓に深く根を張ってきたことがうかがえる。流行を追うのではなく、半世紀以上前に確立した味の輪郭を守り続けている。その一貫が、長く通う人の信頼を支えてきた——それが、ジョージレストランをわざわざ辻まで訪ねる、いちばんの理由になる。",
