      purpose: "辻周辺の街歩きと組み合わせたい人へ",
      desc: "店があるのは那覇市辻、ゆいレールの旭橋駅から海側へ歩いた一角だ。辻は那覇でも古い歴史を持つ町で、かつては花街として栄えた面影をいまも町並みのそこここに残している。近くには那覇港が広がり、海沿いまで足をのばせば波の上ビーチや波上宮も射程に入る。観光の中心である国際通りからも遠くないため、昼に市街を歩き回ったあと、少し外れたこの辺りまで下りてきて食事をする、という組み立てがしやすい。逆に、この店で腹ごしらえをしてから海辺へ向かう順路も気持ちがいい。駐車場はないので、車で向かうなら近隣のコインパーキングを当てにするか、モノレールで旭橋まで来て歩くのが現実的だ。港町の歴史が積もった通りを抜けて扉を開ける——その道のりごと味わうと、一皿の洋食がぐっと立体的になる。歩いて来られる立地は、ゆっくり食事を楽しみたい日にも、海辺の散歩とつなげたい日にも心強い。",
      images: [],
