      purpose: "外で過ごす時間ごと提案を受けたい人へ",
      desc: "店名の後半、by camp gear 12 が示すとおり、この店はコーヒーだけの店ではない。キャンプや登山の道具を扱い、ギアのレンタルや中古買取、さらにアウトドアの手ほどきまで守備範囲に入れている。コーヒー店とアウトドアショップ、一見すると別物の二つが一つの屋号に同居しているのは偶然ではないだろう。外で湯を沸かし、自分の手で淹れる一杯には、家で飲むコーヒーとは別の満足がある。道具を選び、フィールドへ持ち出し、その場で淹れる——その一連の流れを、豆からギアまで一か所で相談できるのがこの店の面白さだ。これからキャンプを始めたい人にとっては、何を揃えればいいか分からない最初のハードルを越える相手にもなってくれる。コーヒーを入口にアウトドアへ踏み出すのも、道具を見にきたついでに豆を選ぶのも、どちらの順番でも成り立つ。暮らしの中の外で過ごす時間を、一杯のコーヒーから設計し直せる場所だと考えると、二つの軸がつながって見えてくる。",
