      desc: "川内珈琲の提案がいちばん分かりやすく出ているのが、時間帯ごとの豆の並べ方だ。朝はすっきりと立ち上がる軽やかな一杯、食後は料理の余韻を流す中庸の一杯、夜は深く落ち着いた一杯、そして野外では手数をかけずに淹れやすい一杯。同じコーヒーを飲むという行為でも、時間が変われば求めるものは変わってくる。その当たり前を、商品の並びとして形にしているのがこの店だ。ドリップパックなら粉を計る手間もミルもいらず、湯さえあればカップ一杯が仕上がる。これ、地味に効く。忙しい平日の朝でも、キャンプ場のテーブルでも、淹れる手順は変わらない。まずは数種類を少しずつ取り寄せて、自分の朝に合う一杯、夜に寄り添う一杯を見つけていくと、日々のコーヒーがほんの少し楽しみになる。豆の在庫やラインナップは時期で入れ替わることがあるので、気になる産地があれば早めに確かめておくと取りこぼしがない。",
