      purpose: "来店の足まわりと回り方を決めたい人へ",
      desc: "川内珈琲のある友泉亭エリアへは、いくつかの行き方がある。電車なら福岡市地下鉄七隈線の別府駅や茶山駅が比較的近く、そこから住宅地を歩いて向かうルートが取れる。西鉄バスなら友泉亭まわりの停留所が使え、天神方面からのアクセスもしやすい。車で訪れる人は、駐車の可否や周辺のコインパーキングをあらかじめ調べておくと、当日あわてずに済む。せっかく城南区まで足を運ぶなら、買い物だけで帰らず、街の時間も少し味わいたい。友泉亭公園で庭園を歩き、季節の草木を眺めてから店に寄れば、選ぶ一杯にも気持ちの余裕が生まれる。アウトドアの相談で長めに話し込みたい日や、豆をじっくり選びたい日は、時間に余裕をもって出かけたい。なお、オンラインでの取り扱いも行っている店なので、店頭の在庫や対応の状況は来店前に確かめておくと安心だ。最寄りの駅やバス停からの細かなルート、当日の営業の有無もあわせて押さえておけば、はじめての城南区さんぽも気持ちよく歩ける。",
