      desc: "sakurayaがあるのは、福岡市城南区堤、油山のふもとを走る油山観光道路沿いだ。住所は堤一丁目、スコーレ堤の一階にあたる。鉄道なら市営地下鉄七隈線の福大前駅が最寄りになるが、駅から店までは歩くと距離があり、徒歩だとそれなりに時間がかかる。バスを併用するか、車で向かう人が多い一帯だが、店に専用の駐車場はないため、車の場合は近隣の停め先を事前に当たっておきたい。周辺には福岡大学や福岡大学病院、さくら病院などが点在し、学生や勤め人、通院帰りの人など、昼夜それぞれに人の流れがある。油山観光道路はその名のとおり油山へと続く道で、堤のあたりは商店や飲食店がぽつぽつと並ぶ生活の通り道だ。観光の目抜き通りではないぶん、地元の人がふだん使いする店が点在し、sakurayaもその一軒として馴染んでいる。営業はおおむね昼の時間帯と夕方以降の二部制で、日曜が休み。仕込みの都合や日替わりの内容で動くこともあるので、目当ての品があるときや夜に確実に座りたいときは、出かける前に電話で空きと当日の献立を確かめておくと、堤まで足を運んでの空振りを避けられる。",
