      desc: "親味の料理の芯は、そばにある。本場の信州そばを土台にしながら、つゆには関西風の利いた出汁を合わせる——産地のそばと土地の味付けを一杯のなかで結ぶのが、この店の組み立てだ。そばの香りを楽しむなら、まずはざるで手繰るのが分かりやすい。天ぷらを添えた天ざるそばは、揚げたての衣とつめたいそばの取り合わせで、そばと天ぷらの両方を一度に味わえる一皿になっている。出汁の利いた関西風のつゆは、温かいそばにすると持ち味がいっそうはっきりして、かけそばや煮込み系の温かい品ともよく馴染む。そばを食事の主役に据えたい人にとって、産地のそばと出汁の取り合わせを軸にした品書きは、頼む前から見通しが立てやすい。何から入るか迷うなら、まずは天ざるそばで、そばと揚げたての天ぷらを並べて味わうところから始めると、この店の手の入れ方が伝わってくる。そばと出汁、それぞれの持ち味がどう噛み合うのかを舌で確かめてほしい。",
