  closing: "そばを目当てに内本町まで足を運ぶなら、まず昼に来るか夜に来るかを決めておくと動きやすい。昼なら、天ざるそばでそばと揚げたての天ぷらを並べて手繰るもよし、丼物や定食でしっかり腹を満たすもよし。買い物や用事の合間に一人でさっと済ませたいときは、カウンターに座って店主の手元を眺めながらの一杯が似合う。夜は、関西風の出汁を生かした温かいそばや、頼んでから揚がる天ぷらを肴に腰を据えるのに向く。数人で来るなら、座敷でそばしゃぶの鍋を囲むと、食事そのものが場の中心になる。所要は、そばや定食でさっと済ませるなら三十分から一時間ほど、鍋を囲んでゆっくりするなら一時間半は見ておきたい。月曜は夜を休むので、夜に訪ねるつもりなら曜日に気をつけたい。車で向かうなら専用駐車場はないため、近くのコインパーキングを使い、駐車券の割引を忘れずに受けたい。席数に限りがあるので、家族連れや座敷を使いたいときは先に席の様子を尋ねておくと安心だ。品書きや営業の予定は時期で動くことがあるため、訪れる前に電話で確かめておくと確実だ。吹田で気のおけないそば処を、生活の地図に一軒書き加えてみてほしい。",
