  titleHTML: "酒蔵 たから屋、<br>駿河湾の<em>夜。</em>",
  subtitle: "駿河湾の魚介と三代の暖簾、清水・相生町の海鮮居酒屋",
  lede: "清水の街は、港と暮らしがすぐ隣り合っている。駿河湾でその朝に揚がった魚が、河岸の市場から街なかの台所へと運ばれ、夜には居酒屋の品書きに姿を変える——そんな循環が、この港町には今も残っている。静岡鉄道の新清水駅から歩いてすぐ、相生町の通りに灯る赤い看板が、酒蔵 たから屋だ。創業からおよそ六十年、いまは三代目が暖簾を引き継ぎ、清水や由比の市場で見つけた魚を肴に出している。気取らない構えと、その日の海の都合で変わる一皿。仕事帰りに一人で立ち寄っても、気の置けない相手と長っ尻に飲んでも、ちょうどいい距離感で迎えてくれる。港町の夜を、魚と酒でゆっくりほどく場所として読んでいきたい。",
