      purpose: "一人でも仲間とでも使いたい人へ",
      desc: "たから屋の居心地のよさは、構えの気取らなさにある。相生町の通りに灯る赤い看板と、魚をあしらった暖簾が目印で、扉をくぐると、長く街に根を張ってきた居酒屋らしい落ち着いた空気が迎えてくれる。一人で来て、その日の魚をつまみながら静かに飲むのにも向くし、気の置けない仲間と魚を分け合って長っ尻に過ごすのにも合う。三代続く店ならではの、客との距離の近さがあるから、初めてでも構えずに入っていける。仕事帰りに一杯ひっかけて帰る夜にも、誰かと約束して港町の魚を囲む夜にも、それぞれの過ごし方で居場所をつくれるのがいい。にぎやかすぎず、かといってよそよそしくもない、ちょうどいい温度。そういう塩梅の店は、街にひとつあると重宝する。混み合う週末や仕事帰りの時間帯は席が埋まりやすいので、人数がまとまるなら電話を入れておくと落ち着いて飲める。",
