      desc: "店があるのは、静岡市清水区の相生町。静岡鉄道の新清水駅から歩いてすぐの距離で、JR清水駅からも徒歩圏にあるので、電車で向かいやすい立地だ。清水は、富士山を望む港と水産の街として知られ、駅の東側へ抜ければ清水港や河岸の市、ベイエリアのドリームプラザまでが徒歩や短いバスでつながっている。清水港のベイエリアには、観光船や寿司の店が集まるドリームプラザ、地元の海産物が手に入る河岸の市があり、休日の昼間をつぶすには事欠かない。サッカーの街としても知られ、試合のある日は街全体が色めき立つ。昼に港や市場をめぐって魚の街の空気に触れ、夜はたから屋で駿河湾の魚を肴に一杯、という一日の組み立てがしやすい。営業は夕方の十七時からの夜営業が中心で、木曜が休みの目安になっている。ただし休みは変わることもあるため、確実に訪ねたい日は事前に営業の予定を確かめておきたい。車で向かう場合は、店専用の駐車場の有無を含めて、周辺のコインパーキングを当てにしておくと慌てずに済む。港町の夜を締めくくる一軒として、街歩きの終点に据えやすい場所にある。",
