  sideArticles: [],
  quote: "港と暮らしが隣り合う清水で、三代にわたって駿河湾の魚と向き合ってきた一軒。その日の海次第で変わる刺身や焼き物を、気取らない温度で出してくれる。魚の街の夜を、肩の力を抜いて飲みたくなったときに思い出したい場所だ。",
  quoteCite: "マチノワ編集部",
  closing: "夕方の十七時に暖簾が出るこの店は、清水の街歩きの締めにちょうどいい時間から動き出す。昼のうちに清水港や河岸の市で魚の街の空気を吸い、日が傾いたころに新清水まで戻ってくる——そんな半日の終点に据えると、一日がきれいにつながる。一人なら、その日のおすすめの刺身を一品もらい、酒を合わせながら海の話を聞くだけでも十分に満ちる。気の置けない相手と来るなら、刺身と焼き物、揚げ物を少しずつ分け合って、長っ尻にやるのがこの店らしい。所要は、軽く飲むなら一時間ほど、腰を据えて魚を堪能するなら二時間ほどを見ておくといい。予算は夜で五千円前後が目安になるが、その日の魚や頼む品で動くので、気になるなら席についたときに尋ねておくと安心だ。週末や仕事帰りの時間帯は混みやすいから、人数がまとまる日は電話を一本入れてから向かいたい。木曜の休みも、念のため確かめておくと無駄足にならない。日が落ちてからの相生町は、駅前の人通りからは一歩引いた静けさがあり、魚をあしらった赤い看板の灯りがよく目立つ。清水まで足を延ばすなら、富士山を望む港の景色もあわせて楽しみたいところだ。清水で魚と酒を、と思った夜の行き先に、この一軒を加えてみてほしい。",
