  lede: "那覇の中心を貫く国際通りから一本入った牧志一丁目は、土産物店のにぎわいとすぐ隣り合いながら、地元の人が日常的に通う飲食店が静かに灯るエリアだ。野菜の酒場。クサワケセカンドは、栄町市場で野菜料理の居酒屋として知られた本店から派生し、この久茂地・牧志の界隈に根を下ろした一軒。店の軸にあるのは「野菜で飲める店」という発想で、無農薬の野菜を主役に据え、前菜から温菜まで野菜のうまさで杯を進められる構成になっている。観光客も地元客も分け隔てなく迎え、国際通りから徒歩5分という立地は、観光の合間にも仕事帰りにも寄りやすい。旅の夜に沖縄の野菜で軽く一杯、という使い方がよく似合う店だ。",
