      desc: "店はビルの一階にあり、総席数は30席ほど。12席のカウンターと、6名掛けのテーブルが複数用意されているので、一人で来てカウンターに腰を据えるのも、数人で卓を囲むのも無理がない。カウンターなら、目の前で供される野菜の一皿を肴に、店の人と言葉を交わしながら静かに飲める。テーブル席は、仕事仲間や友人とゆっくり取り分けながら過ごすのに向く。25名以上であれば貸切にも対応するので、職場の集まりや旅の仲間との宴会にも使える幅がある。野菜中心という性格上、女性同士や、健康を気にかける人にとっても入りやすい空気がある。観光客と地元客が同じ空間で杯を傾けるので、那覇の夜の温度を肌で感じながら飲めるのもこの店らしい。カウンターは料理の手元が見える特等席で、何を頼むか迷ったらその場で相談しながら決められるのもいい。一人の晩酌から大人数の宴席まで、その日の人数と気分に合わせて居場所を選べる懐の深さがあるので、旅程や同行者が変わっても使い回しのきく一軒として覚えておきたい。",
