      desc: "店があるのは那覇市牧志一丁目、国際通りから歩いて5分ほどの場所だ。最寄りはゆいレールの県庁前駅と美栄橋駅で、どちらからも歩いて向かえる距離にある。国際通りの土産物店や市場をひと通り巡ったあと、にぎわいから一本入ってこの店で落ち着いて飲む、という流れが組みやすい。昼から第一牧志公設市場や周辺のアーケードを歩き、沖縄の食材や工芸に触れてから、日が暮れたころに野菜の酒場へ――そんな一日の締め方が似合う立地だ。観光の拠点になるホテルの多くが国際通り沿いにあるため、宿に帰る前の一杯にも寄りやすい。営業は夕方16時から。曜日によって閉店時間が変わり、金曜と土曜、祝前日は深夜まで開いているので、遅い時間からでも滑り込める。不定休のため、確実に訪ねたい日は営業日を事前に調べておくと安心だ。空港からモノレールで中心部へ入り、国際通りで遊んでから締めに寄る、という旅程にもはめ込みやすい一軒だ。",
