  sideArticles: [],
  quote: "国際通りのにぎわいから一歩入った牧志で、野菜を主役に飲ませてくれる一軒。栄町の本店ゆずりの発想を、観光と日常が交わる久茂地に下ろした店だ。沖縄まで来て、胃をいたわりながら飲みたくなった夜に思い出したい場所である。",
  quoteCite: "マチノワ編集部",
  closing: "国際通りで遊んだ余韻を野菜とともに静かにほどきたいなら、夕方からの時間にこの店を据えるのが収まりがいい。昼のうちに公設市場や土産物店を巡り、日が傾いたころに牧志一丁目へ戻ってくる――そんな一日の終点にちょうどはまる立地だ。一人で訪れるなら、カウンターに腰を据えてベジプレートを一皿、酒を一杯から始め、野菜の味を確かめながらゆっくり杯を重ねるのがいい。二人や少人数なら、前菜と温菜、魚介を少しずつ頼んで、酒を料理に合わせて変えていくと、野菜だけで思いのほか飲める夜になる。旅の仲間とにぎやかにやるなら、人数しだいで貸切も視野に入る。所要は、軽く飲むなら一時間ほど、腰を据えるなら二時間ほどを見ておくと過不足ない。予算はアラカルトと酒の頼み方しだいで動くので、気になるなら席についたときに尋ねておくと安心だ。週末や祝前日は深夜まで開いているぶん混み合いやすいので、人数がまとまる日は電話を一本入れておきたい。不定休なので、目指す日が決まったら営業日を確かめてから向かうと無駄足にならない。那覇の夜を、肉でも揚げ物でもなく野菜で締めくくる――その選択肢を持っておくと、旅の一日がもう少し軽やかになる。",
