      purpose: "食事目的でも選べる、料理の軸を伝える",
      desc: "牧志プリーストの料理の軸は、生地から手作りするパスタとピザにある。市販の麺や既製の生地に頼らず、店で粉から仕込むことで、ゆで上がりのもちもちした食感や、焼き立てのピザの香ばしさが生きてくる。手間のかかるやり方だが、一皿の満足度を底から支えているのはこの下ごしらえだ。パスタはトマトの辛みをきかせたアラビアータや、大葉を使った和の香りのジェノベーゼなど、定番からひとひねりしたものまでそろう。深夜まで開く店というと軽いつまみだけを想像しがちだが、ここはしっかり食事として向き合えるイタリアンだ。だからこそ、飲みの締めに一皿だけ手繰るのもいいし、最初から食事を目的に腰を据えるのもいい。一品の質で選べる店なので、観光や仕事で疲れた夜でも、ちゃんとしたものを食べたいという気持ちに応えてくれる。品書きは時期で入れ替わることがあるため、その日のおすすめは席についてから尋ねてみるのがいい。",
