      purpose: "夜遅くに使える価値を伝える",
      desc: "この店のいちばんの個性は、開店が夕方で、翌1時まで灯りがともる営業時間の長さにある。多くの飲食店が早い時間に閉まるなか、夜が更けてから本格的な食事にありつける店は、那覇の中心でもそう多くない。料理のラストオーダーは深夜0時、ドリンクは0時半まで受けてくれるので、遅い時間に着いても慌てずに済む。国際通り周辺で一軒目を楽しんだあと、二軒目や締めとして流れてくる――そんな夜の組み立てに自然にはまる立地と時間だ。観光で動き回って食事が後ろにずれ込んだ日や、仕事を終えてから一息つきたい夜にも頼りになる。手作りのパスタやピザを軽くつまみながら一杯やれば、長い一日の締めくくりにちょうどいい。深夜営業の店は料理が手薄になりがちだが、ここは生地から作る料理をその時間まで出すという点で一線を画している。営業時間や定休日は天候などで変わることがあるため、訪れる前に最新の状況を確かめておきたい。",
