      desc: "品書きはパスタとピザだけにとどまらない。じっくり火を入れたスペアリブは、肉をしっかり食べたい夜の主役になる一皿で、骨ごとかぶりつく満足感がある。ふわりと仕上げたスフレオムレツにポルチーニのソースを合わせた一品は、卵料理ながら手の込んだ味わいで、シェアして取り分けるのにも向く。前菜から肉料理まで少しずつ頼んで、ワインやドリンクと合わせていけば、カジュアルながらコース仕立てのように夜が進んでいく。何品か頼んで分け合うのが似合う構成なので、二人でも、数人のグループでも楽しみやすい。じっくり食事を組み立てたいなら、コース仕立てで頼む手もある。アラカルトで気ままに攻めるか、コースで通すか、その日の人数と気分で選べるのがいい。メニューや価格は時期で動くので、訪れる前に電話や公式の案内で確認しておくと確実だ。気になる一皿があれば、まずはその日のおすすめと合わせて相談してみてほしい。",
