      desc: "牧志プリーストがあるのは、那覇市牧志の二丁目。沖縄モノレールの美栄橋駅から歩いて六分ほどの距離で、国際通りや第一牧志公設市場といった那覇観光の中心地からも近い。昼間は市場や商店街を巡り、夕方からは国際通りで土産を選び、夜が更けたらこの店で腰を落ち着ける――一日の終着点として組み込みやすい立地だ。観光客でにぎわう表通りから一本入るので、人混みから離れて落ち着ける点もいい。周辺には飲食店やバーが多く、一軒目をどこかで軽く済ませてから流れてくるのも、ここを拠点に二軒目へ繰り出すのも、どちらも自然にできる。国際通り界隈には宿泊施設も多いため、那覇に泊まる旅程なら、ホテルから歩いて行ける夜の食事処として頼りになる。モノレールの駅から近いので、空港から那覇入りした日でも、荷物を置いてそのまま向かいやすい。にぎわうエリアだけに週末の夜は人通りも多く、目当ての時間に座りたいなら、あらかじめ予約しておくと迷わずに済む。",
