      desc: "げっとらが名物に据えるのが、純レバテキだ。新鮮なレバーを使い、生に近い火入れで仕上げる一品で、口に運ぶととろりと崩れる食感とレバー本来の甘みが広がる。レバーは鮮度が命の食材で、状態が悪ければ独特の臭みが出てしまうが、ここのレバテキはその点で評判をとってきた。臭みを抑えた澄んだ味わいは、レバーが得意でない人にとっても入口になりやすい。タレや薬味と合わせれば、ビールやハイボールはもちろん、日本酒や焼酎ともよく寄り添う。レバーは火を通しすぎると硬くもそもそとした口当たりになりがちだが、半生に近い火加減で供されるからこそ、なめらかな舌触りが際立つ。最初の一皿にこれを頼んでおけば、店の素材への向き合い方が伝わってくる。なお、生に近い火入れの提供は仕入れや状態によって内容が変わることがあるため、気になるときは席についた折に店の人へ尋ねておくと確実だ。",
