  lede: "阪神西宮駅から北へ数分歩くと、市役所や図書館が並ぶ六湛寺町の落ち着いた一画に出る。カフェ・トム・トムがあるのは、その市役所のすぐ隣だ。朝八時、官庁街が本格的に動き出す前から店の灯りはともり、近隣で働く人や常連がコーヒー一杯を求めて入ってくる。西宮は灘の酒造りを支える名水「宮水」が湧く街で、この店はその宮水で淹れたコーヒーを看板にしている。夫婦で切り盛りする喫茶店らしく、モーニングからランチ、午後のケーキタイムまで、一日のどの時間に立ち寄っても居場所になるのがいい。観光のために構えた店ではなく、西宮で暮らし働く人の日常にすっと溶け込んだ一軒——そんなトム・トムの居心地と使い方を、街の文脈とあわせて見ていきたい。",
