      purpose: "誰と、どう過ごせるかを示す",
      desc: "席の構成は、市場の食堂らしく幅がある。店にはカウンター席とテーブル席があり、加えて総合食品センター棟のフードコート用テーブルも使える。一人で市場に立ち寄って、カウンターで海鮮丼を手早く一杯——という使い方もできれば、連れと向き合ってテーブルでゆっくり魚を囲むこともできる。家族で来てフードコートの広いテーブルに陣取れば、それぞれ好きなものを頼んで集まる、という市場ならではの食べ方も成り立つ。全席禁煙で、かしこまった料理屋の緊張感はない。あくまで市場のにぎわいの延長にある食事処なので、子ども連れでも肩肘張らずに過ごせる。予約は受けていないため、混み合う時間に当たれば待つこともあるが、その分ふらりと立ち寄れる気軽さがある。一人の朝めしから家族連れの昼まで、来店のしかたを選ばないのがこの店の居心地だ。",
