      purpose: "店までの道のりと街での組み込み方を示す",
      desc: "大幸亭があるのは、和歌山市西浜の和歌山市中央卸売市場。最寄りは南海和歌山港線の和歌山港駅で、そこから歩いて十分ほどだ。和歌山港は徳島へ渡る南海フェリーの発着地でもあり、港と市場が隣り合う海辺の一帯にある。車で訪れる人のために駐車場も備わっているので、市内のどこからでも立ち寄りやすい。せっかく市場まで来たなら、丼を食べる前後に総合食品センター棟をひと回りするのがいい。鮮魚や食料品、雑貨の店が軒を連ね、市場の活気をそのまま味わえる。買い物のついでに海鮮丼を挟む、あるいは海鮮丼を目的に来て市場を冷やかす——どちらの順序でも半日の小旅行になる。和歌山港からは徳島へ渡る南海フェリーも出ており、四国へ向かう前後にこの一帯で腹ごしらえをする、という旅程に組み込むこともできる。市場は朝が主役なので、昼までに動くのがこの界隈の歩き方に合っている。港の風と市場のにぎわいを、ひとつの道のりでつなげられる立地だ。",
