  quote: "魚が集まる場所で、魚を食べる。大幸亭の魅力はその一点に尽きる。和歌山市中央卸売市場が市民に開いた「わかやままるしぇ」の一角で、市場仕込みの海鮮丼を気軽に味わえる一軒だ。観光の海鮮処では味わえない、現場の鮮度と市場の活気を、丼ひとつで受け取れる場所として覚えておきたい。",
  quoteCite: "マチノワ編集部",
  closing: "市場は朝が主役だから、この店も午前のうちに動くのが似合う。和歌山港駅から海辺を十分ほど歩いて、まずは中央卸売市場の総合食品センター棟「わかやままるしぇ」へ。鮮魚や食料品の店をひと回りして市場の空気をつかんでから、大幸亭のカウンターで海鮮丼を一杯——という流れが、この界隈にいちばん収まりがいい。一人なら、丼を手早く味わってそのまま港まで足を延ばすのも気持ちがいい。家族や連れと来るなら、フードコートの広いテーブルに陣取って、それぞれ好きなグレードの丼を頼んで分け合うのが市場らしい楽しみ方だ。予約は受けていないので、混む時間を避けたいなら開店から間もない時間を狙うと落ち着いて食べられる。所要は、丼一杯なら三十分ほど、市場を見て回るなら一時間ほどを見ておくと過不足ない。予算は丼のグレード次第で気軽な一杯から贅沢な一杯まで幅がある。営業時間や定休日、丼の内容は時期や入荷で変わることがあるので、訪れる日が決まったら来店前に電話で確かめておくと確実だ。水曜が定休なので、その点だけ頭に入れて出かけたい。",
