      desc: "この店の顔は、何といってもポテトニャロスだ。猫のしっぽをイメージしたという細長い形のポテトフライで、その見た目のユニークさがまず目を引く。ただ形が変わっているだけではない。表面はザクザクと香ばしく揚がり、中はモチモチとした食感を残す——この対比が、ありふれたフライドポテトとは違う一本に仕上げている。片手で気軽につまめる軽さでありながら、噛むほどに芋の存在感が伝わってくるので、食べ歩きのおやつとしても、ちょっとした空腹を満たす一品としても収まりがいい。テイクアウト中心の店だから、受け取ってそのまま店先や近くで頬張るのが似合う。隣でラーメンを食べたあとの口直しに甘くないものを少しだけ、という使い方もできるし、子どもと分け合うにもちょうどいいサイズ感だ。奇抜な名前と形に反して、味の芯はまっとうなポテトフライ。だからこそ、一度試すと宇都宮で小腹が空いたときに思い出す一本になる。",
