  quoteCite: "マチノワ編集部",
  closing: "テイクアウトが中心のこの店は、長く腰を据える場所というより、何かの合間にすっと立ち寄る一軒だ。だから宇都宮・峰での過ごし方も、その軽さに合わせて組み立てたい。車で訪れるなら、目印は麺道 花の杜。その敷地内に庭先のように店があるので、共用の駐車場に停めて歩けばすぐにたどり着く。迷ったら、看板のポテトニャロスを一つ、ディップを一種だけ選んで試すのがわかりやすい。表面のザクザクと中のモチモチを確かめてから、次に来たときに別のディップへ進めばいい。甘いもので締めたいならクレミアのソフトクリームを足して、テラス席で頬張れば、それだけで小さな休憩時間になる。子ども連れなら、猫のしっぽ型のポテトを分け合うだけで場が和むはずだ。隣の花の杜でラーメンを食べたあとのデザート代わりに寄るのも、買い物や散歩の途中で一服するのも、どちらも無理がない。所要は、ささっと買って食べるだけなら十数分、テラスでゆっくりしても三十分ほど見ておけば足りる。営業は木曜が休みなので、その点だけ頭に入れておきたい。メニューや価格は時期で動くことがあるので、狙いの一品があるなら訪れる前に確かめておくと確実だ。",
