    lede: "阪急今津線の門戸厄神駅を降りて、ほんの一分。旧西国街道にほど近い門戸荘の一角に、魚幸処にしかわはある。二〇二四年の夏、かつて銀座鮨があった場所に開いた魚の定食屋で、阪神間で魚のうまい店として知られる宝塚のまるさん松本の系列にあたる。看板に掲げるのは、その日の魚を主役にした造りや天ぷら、海鮮丼。駅前という通いやすさと、系列ゆずりの目利きが重なって、昼はしっかり魚の定食、夜は造りや一品で軽く一杯と、一日のうち何度でも立ち寄りたくなる構えになっている。門戸荘という住宅地に魚の店が一軒あるだけで、街の食卓の選択肢はぐっと豊かになる。門戸厄神というこの街で、にしかわが日々の食事をどう支えているのか、駅からの道のりや料理、使い方まで、編集部の視点でたどっていきたい。",
    date: "2026-06-19",
