        purpose: "店の核となる一皿を知る",
        desc: "魚幸処にしかわの核は、その日に仕入れた魚を主役に据えた造り定食にある。店名に魚の幸を掲げる通り、品書きの真ん中には刺身が居座り、盛りを豪華にした造り定食が看板格として案内されている。魚の定食屋でありながら、その日の入荷で内容が動くのが面白いところで、季節ごとに膳の顔ぶれが変わっていく。淡路島の魚を組んだ定食が用意されることもあり、瀬戸内に近い土地の利が、そのまま皿の上に表れている。系列の宝塚まるさん松本は、魚のうまい店として阪神間で名の通った一軒で、その目利きの延長線上に、この駅前の定食がある。だから昼にしっかり魚を食べたい時、まず頼みたいのがこの造り定食だ。何を選べばいいか迷ったら、その日のおすすめを店の人に尋ねてみるのが、一番の近道になる。仕入れ次第で内容は日々変わるので、狙いの魚があるなら来店前に電話で聞いておくと確実だ。良い魚を素直に味わう、その一点でこの店は組み立てられている。",
