        purpose: "他店と違う理由を示す",
        desc: "にしかわを近隣で代えのきかない一軒にしているのは、その出自だ。阪神間で魚のうまさを知られる宝塚のまるさん松本の系列という背景は、毎日の魚選びにそのまま効いてくる。名のある魚の店の流儀を、駅前の通いやすい定食屋という形で受け取れる——そこにこの店の値打ちがある。気構えのいる鮨割烹ではなく、昼は定食、夜は造りや一品で軽く一杯、という日常の距離感で系列の魚に触れられるのは、地味に効く強みだ。かつてこの場所にあった銀座鮨の跡を受け継ぐように、二〇二四年から魚の店としての営みが続いている。門戸厄神の駅を出てすぐという立地も後押しして、買い物帰りやちょっとした夜の一杯にも寄りやすい。かしこまらずに良い魚を食べたい、そんな日の選択肢として頼りになる。系列で培われた目利きを構えず味わえる、その手の届きやすさが、わざわざこの店を選ぶ理由になっている。宝塚の本店で魚に親しんだ人にとっても、門戸厄神でその系譜に出会えるのは、ちょっとした発見になるはずだ。鮨屋ほど身構えず、それでいて魚にはきちんとこだわる——その中間の心地よさが、この店の居場所になっている。",
