        desc: "品書きは造りだけにとどまらない。揚げたての天ぷらを組んだ定食、魚をのせた海鮮丼、淡路島の魚を主役にした定食と、魚を多面的に楽しめる構成になっている。定食のほかに一品もので、魚のあら汁や焼き魚、たこわさといった酒に合う皿も用意されていて、夜は造りをつまみに軽く飲む使い方もできる。あら汁は魚のうまみを汁にそのまま落とし込んだ一杯で、定食に添えれば食卓の満足感がぐっと増す。さらに刺身や海鮮丼、天ぷらを詰めたテイクアウトの弁当も扱っていて、家で魚を食べたい日や、持ち帰って家族と分けたい時に重宝する。一つの店で、刺身も揚げ物も丼も、そして持ち帰りまで魚をひと通りまわせるのが、使い勝手のいいところだ。値段は定食でおおむね千円台から二千円前後が中心だが、内容や価格は時期で動くことがあるので、訪れる前に電話や公式サイトで確かめておくと安心だ。テイクアウトを使えば、店の魚をそのまま自宅の食卓に持ち込めるのも、近所に住む人には心強い選択肢になる。",
