        desc: "店内は、カウンター八席に四人掛けのテーブルが二卓という、こぢんまりとした構えだ。大箱ではないぶん、一人でふらりと寄って定食を手早く食べるのにちょうどよく、カウンターなら気兼ねなく目の前の一皿と向き合える。四人掛けのテーブルが二卓あるので、家族連れや友人との小さな集まりにも応える。昼は定食でさっと済ませる人、夜は造りをつまみに一杯やる人と、時間帯で使われ方が変わるのも、この規模の店ならではの光景だ。駅前の定食屋という気取らない空気で、はじめての人でも入りやすい。席数が限られるぶん、人数のまとまったグループや混み合う時間に行くなら、前もって電話を一本入れておくと落ち着いて座れる。予約や問い合わせは電話のほか、店のインスタグラムからも受け付けている。一人の昼にも、数人での夜にも収まる——その間口の広さが、日常使いの一軒として頼もしい。魚の店らしく、カウンター越しに仕込みの気配を感じながら食べられるのも、この距離感ならではの楽しみだ。",
