        desc: "場所は西宮市門戸荘、旧西国街道に近い一帯にある。最寄りは阪急今津線の門戸厄神駅で、歩いておよそ一分という近さだ。門戸厄神という駅名は、すぐ近くにある厄除けの寺、門戸厄神東光寺に由来する。厄神さんへの参りの行き帰りに、魚の定食で一息つく——そんな組み立てができる立地でもある。営業はおおむね昼の十時半から十五時、夕方の十七時から二十一時の二部制で、木曜が定休だ。昼と夜のあいだに中休みがあるので、その時間帯だけは頭に入れておきたい。駐車場は店舗に備えがないため、車で向かうなら近隣のコインパーキングを使うことになる。電車なら駅からほぼ一直線で、傘いらずの近さが雨の日にもありがたい。予約や問い合わせは電話で受けていて、受付はおおむね営業時間に合わせている。門戸厄神の門前にあたる落ち着いた界隈なので、参道のあたりを歩いてから店に向かえば、ちょっとした小旅行のような気分も味わえる。営業時間や定休日は変わることがあるため、出かける前に最新の情報を確かめておきたい。",
