    sideArticles: [],
    quote: "魚幸処にしかわは、門戸厄神の駅前で、まるさん松本系列ゆずりの魚を気取らず出してくれる定食屋だ。その日の造りから天ぷら、海鮮丼まで、昼の一食にも夜の一杯にも応えてくれる。良い魚を構えずに食べたい——西宮でそんな気分になった日に、まず思い出したい一軒だ。",
    quoteCite: "マチノワ編集部",
    closing: "門戸厄神の駅を出て一分という近さは、この店の使い方をそのまま決めてくれる。電車で向かうなら、改札からほぼ一直線で着くので、買い物や用足しのついでにも立ち寄りやすい。最初の一食に迷ったら、その日の造り定食を選んでおけば、この店が魚で勝負している意味がすぐに伝わる。物足りなければ、あら汁や天ぷらを一品足すと魚の楽しみ方が広がる。一人なら、カウンターで定食をさっと、あるいは造りをつまみに軽く一杯。家族や友人とならテーブルを囲んで、刺身や天ぷらを分け合うのが似合う。所要は、昼の定食だけなら一時間ほど、夜にゆっくり飲むなら一時間半ほど見ておけば足りる。昼と夜のあいだに中休みがあり、木曜は休みなので、その二点だけは出かける前に押さえておきたい。すぐ近くの門戸厄神東光寺に参ってから魚で一息、という半日の組み立ても、この立地ならよく収まる。気負わず良い魚に会いに行く、その駅前ならではの距離感こそが、この一軒のいちばんの心地よさだ。",
