    lede: "蛍池は、阪急宝塚線と大阪モノレールが交わる乗換駅だ。モノレールに乗ればひと駅で大阪空港(伊丹)に着き、阪急で梅田へも宝塚へも出られる——人の行き来が絶えない結節点でありながら、駅を離れれば住宅と商いが入り混じる落ち着いた街でもある。その蛍池駅のすぐそば、国道176号沿いに灯るのが焼肉ほたる翔だ。二〇二〇年二月末にこの地で開いた焼肉店で、黒毛和牛と希少部位、自家製のタレを軸に、夜だけ店を開けている。乗換のついでに立ち寄れる立地でありながら、出てくる一皿は腰を据えて向き合いたくなる肉だ。仕事帰りに一人で炭を囲むのにも、家族や気の置けない相手と部位を焼き分けながら長居するのにも、どちらにも応えてくれる。空港にも梅田にも近い駅前で、わざわざ降りて肉を焼く理由になる一軒——その輪郭を、編集部の視点でたどっていきたい。",
