        desc: "ほたる翔の芯にあるのは、黒毛和牛をはじめとする肉の質と、それを受け止める自家製のタレだ。焼肉店は数あれど、扱う肉の格と部位の幅で店の性格は大きく分かれる。この店は黒毛和牛を看板に据え、ハラミやハネシタロース、赤身のモモ、イチボといった部位を取りそろえる。サシの入り方も、噛んだときのほどけ方も部位ごとに違うから、同じ黒毛和牛でも一皿ごとに表情が変わる。霜降りの甘みを楽しみたいならハネシタロース、肉の味そのものを噛みしめたいなら赤身のモモやイチボ——という選び分けができるのが、部位をきちんと並べる店の強みだ。そこに合わせるのが自家製のタレで、肉の脂や旨みを流さずに受け止める役を担う。市販のタレに頼り切らず、店の味として組み立てているからこそ、肉の個性とのバランスが取れている。塩で食べるか、タレにくぐらせるか、その日の部位と気分で決められる。まずは希少部位を一枚、炭の上でさっと焼いて口に運ぶと、この店が肉のどこで勝負しているかがいちばん素直に伝わってくる。",
