        desc: "注文を組み立てるうえで頼りになるのが、人数に合わせた肉盛りセットだ。二名向けから四名、六名向けまで段階が用意されていて、何を頼むか迷ったときはこのセットを軸にすると部位をまんべんなく味わえる。肉そのものをしっかり食べたい日には、ハネシタロースや赤身もも、イチボのステーキという選択肢もある。薄切りを炭で焼くのとはまた違う、厚みのある肉の満足感が得られる。ホルモンはテッチャンや上ミノ、焼きレバーを単品で、あるいはMIXで。締めにはビビンバやユッケジャンクッパ、冷麺がそろい、テールスープやユッケジャンスープで体を温めることもできる。脂の多い部位を焼いたあとに冷麺でさっぱりと終える、あるいはユッケジャンでもう一押し満腹まで——という締めの選び方ができるのも、ご飯ものと麺の両方を持つ店ならではだ。肉からご飯もの、汁物まで一通りそろうので、焼いて終わりではなく食事として落ち着く。メニューや価格は時期で動くことがあるので、狙いの部位やセットがあるなら、訪れる前に電話で確かめておくと確実だ。何を選んでも、土台にあるのは黒毛和牛という芯だ。",
