        desc: "ほたる翔は夜だけ営業する焼肉店で、夕方から夜にかけての時間に腰を据えて使う一軒だ。予約を受け付けているので、人数や日取りが決まっているなら席を押さえておくと当日が滑らかになる。仕事帰りに一人で数皿を炭で焼く静かな夜にも、家族や気の置けない相手と部位を焼き分けながら長居する夜にも向く。黒毛和牛と希少部位を中心に据えた価格帯なので、毎日の焼肉というより、ちょっといい肉を囲みたい日や、節目の食事に合わせやすい。乗換駅のすぐそばという立地は、それぞれ別の方面から集まって一卓を囲むのにも都合がいい。蛍池で待ち合わせて、そのまま炭の前に座る——そんな使い方が自然にできる。混み合う時間帯は日によって変わることがあるため、確実に座りたい日は事前に店へ問い合わせておくと安心だ。誰と、どんな夜に来るかで、頼む部位も滞在の長さも自在に変えられる店だ。",
