        desc: "店があるのは蛍池駅のすぐそば、国道176号沿いだ。阪急宝塚線と大阪モノレールの二線が乗り入れる蛍池駅から歩いて二分ほどで、雨の日でもほとんど濡れずに近づける距離にある。モノレールに乗ればひと駅で大阪空港(伊丹)に出られるので、飛行機の前後にこの街で食事を挟むという旅程にも組み込める。阪急で梅田からも宝塚からも一本で来られるため、それぞれ違う方面から集まりやすいのも蛍池という駅の利点だ。駅前には商業施設もあり、待ち合わせまでの時間をつぶすにも困らない。肉を焼く前に駅前で軽く落ち合い、店でゆっくり食べて、帰りはそれぞれの路線で散っていく——乗換駅ならではの解散のしやすさがある。車で訪れる人にとっても、幹線の176号沿いという分かりやすい立地だ。空港にも繁華街にも近い結節点で、わざわざ途中下車して炭を囲む——その手軽さと贅沢さが同居しているのが、この立地の面白さだ。",
