    closing: "夜だけ開く店だから、この一軒を中心に据えるなら夕方以降の時間を空けて向かいたい。蛍池駅から国道176号沿いに歩いて二分、阪急でもモノレールでもたどり着けるので、それぞれ別の方面から集まって一卓を囲むのに向いている。初回は、人数に合わせた肉盛りセットを軸に、希少部位を一枚ずつ追いながら店の肉を見渡すのがいい。一人なら、カウンター感覚で数皿を炭で焼き、締めに冷麺やクッパで終えるくらいがちょうどいい。家族や気の置けない相手となら、和牛の部位とホルモンを端から焼き分けて、ゆっくり長居するのが似合う。黒毛和牛を中心にした価格帯なので、節目の食事やちょっといい肉を囲みたい夜に合わせやすい。所要は、軽く数皿なら一時間ほど、しっかり食べ進めるなら二時間ほどを見ておくと過不足ない。予約を受けているので、確実に座りたい日や人数が読めている日は、席を押さえてから出かけたい。営業時間やメニュー、価格は変わることがあるため、来店前に最新情報を確かめておくと、安心して炭の前に座れる。",
