        desc: "定食と並ぶもう一枚の看板が、デカ皿カレーだ。名前のとおり、大きな皿にたっぷりと盛られた一皿で、食べ盛りや、しっかり昼を取りたい日に応える。チェーンの均一なカレーとは違い、ここのカレーも店で手作りされた一皿で、定食の手作り路線とぶれていないのがいい。この店に通いたくなる理由は、突き詰めれば手作りという一点に尽きる。冷凍の食材を使わず、揚げ物もカレーも日替わりのおかずも店で仕込む。だからこそ、毎日来ても飽きが来にくく、日替わりを目当てに足が向く。価格を千円前後に抑えながら手間を惜しまない——この両立が、近くで働く人たちの昼を長く支えてきた。派手な仕掛けがあるわけではないが、毎日の昼として信頼できることが、ここでは最大の強みになる。メニューや価格は時期で動くことがあるので、狙いの一皿があるなら、訪れる前に電話で確かめておくと確実だ。",
