    lede: "広畑駅から南へ歩いて数分、住宅と小さな店が混ざり合う一角に、赤い看板を掲げた二階建てがある。お好み焼き・一品料理 じゃがじゃが——夢前川の河口に広がる日本製鉄広畑地区とともに育った、この働く街で、鉄板を囲んで一日を締められる一軒だ。広畑は製鉄所とともに歩んできた暮らしの街で、駅前から少し離れれば、車で立ち寄れる地元の食事処が点々と続く。じゃがじゃがもそのひとつで、観光客でにぎわう姫路城まわりとは違う、生活のなかにある鉄板店の顔をしている。火曜から土曜は夕方の十六時半から、日曜だけは昼の十一時半から店を開けるので、平日の仕事帰りにも、休日の昼にも顔を出せる。鉄板の前で過ごす時間も含めて楽しめる、お好み焼きと一品料理を軸にしたこの店を、立地と使い方の両面から見ていきたい。",
