    lede: "江ノ電の踏切と波の気配が近い、鎌倉市由比ガ浜三丁目。観光客で賑う小町通りとは表情の違う、地元の生活道路沿いの一角に、USHIWAKAMARUはある。2022年8月に開業した焼肉店で、看板を探さなければ通り過ぎてしまうほど静かな構えの二階だ。中心にあるのは、脂身の少ない赤身肉と熟成肉。漢方ハーブを食べて育った和牛や希少部位を、無添加の野菜や自家製キムチとともに無煙ロースターで焼く。器やワインへのこだわりも見え隠れし、個室はなくテーブル席中心という構成もあって、観光の合間に立ち寄る店というより、鎌倉に暮らす人や、静かに一軒で肉と向き合いたい人に向く店だ。",
