        area: "神奈川県鎌倉市",
        purpose: "この店の看板が「脂の多い霜降り」ではなく「赤身と熟成」であることを示す",
        desc: "USHIWAKAMARUの中心にあるのは、脂身の少ない赤身肉と熟成肉だ。漢方ハーブを食べて育った和牛や、赤牛といった品種の希少部位を、その日ごとに揃える。多くの焼肉店が霜降りの脂の甘みを前面に出すのに対し、この店は赤身そのものの旨みと、熟成による香りの変化を軸に据えている。野菜は無添加のものを選び、白砂糖を使わず素材由来の甘みで味を組み立てる。自家製のキムチも添加物を使わずに仕込むという。付け合わせの米は有機米、汁物には野菜のスープが添えられ、デザートには自家製アイスクリームや有機コーヒー・ハーブティーを用意し、焼肉単体で完結させずコース全体で満足させる構成だ。無煙ロースターを備えているため、煙や匂いを気にせず、赤身と熟成肉それぞれの食感の違いを追いながら食事を進められる。",
