        desc: "USHIWAKAMARUは、肉の質だけで完結する店ではない。使う陶器やグラスにも店主のこだわりが表れており、希少なワインを含む酒の品揃えを用意するなど、酒の面でも一般的な焼肉店とは違う顔を持つ。調味料も妥協せず選び、白砂糖を使わず素材の甘みを活かすなど、味の組み立て方に一貫した方針がある。安心・安全な食材にこだわるという店の姿勢は、野菜やキムチの添加物不使用という選択にも表れている。竹や木を使った落ち着いた内装は、煙が充満しがちな焼肉店の印象とは距離があり、二階という立地もあって、通りから偶然入るというより、目的を持って訪れる隠れ家的な一軒という性格が強い。肉の焼き方だけでなく、器や酒の組み合わせを変えながら季節ごとに通いたくなる店だ。",
