        desc: "最寄りは江ノ電の和田塚駅で徒歩数分、隣の由比ヶ浜駅からも徒歩3分ほどと、どちらの駅からもアクセスしやすい。JR・江ノ電の鎌倉駅からは徒歩10分強で、鎌倉駅周辺の賑わいから少し離れた、地元の生活道路沿いという立地が店の静けさにつながっている。なお店の住所表記は「由比ガ浜」だが、最寄り駅の名は「由比ヶ浜駅」と、同じ地名でも仮名の表記が異なる点は鎌倉らしい土地の細部だ。屋号のUSHIWAKAMARUは、源義経の幼名として知られる牛若丸に由来すると見られる。義経は鎌倉入りを兄・頼朝に許されず、同じ江ノ電沿線の腰越にある満福寺に留め置かれたという逸話で知られる人物で、由比ガ浜という海沿いの土地に立つと、その名がふと重なってくる。由比ガ浜海水浴場の散策や、江ノ電での小さな移動と組み合わせて、食事の締めくくりに使うのに向いた立地だ。",
