    lede: "愛知環状鉄道六名駅から歩いて数分、乙川に近い住宅街に公園やスーパーマーケットが点在する岡崎市江口。観光地の中心というより、暮らしの延長線上にある落ち着いた一帯に、2025年7月7日「天然昆布水つけ麺 礼音」が開店した。化学調味料を使わず一等級の天然昆布を水出ししただし汁に、京都の製麺所による中太平打ち麺を浸すつけ麺専門店として昼夜二部制で営み、土日は予約制の鮨懐石ももう一つの看板として掲げる。手間をかけた昆布水とつけ麺をじっくり味わいたい人にも、週末に少人数で落ち着いて鮨を囲みたい人にも、目的と曜日を選んで応える一軒だ。",
