        desc: "礼音の軸になっているのが、化学調味料を使わずに一等級の天然昆布を低温でじっくり抽出し、さらに性格の異なるもう一種の昆布を加えて一〜二日ほど冷蔵庫で寝かせる「昆布水」だ。抽出された昆布水はとろみを帯び、旨みの輪郭がはっきりしているのが特徴とされる。麺は京都の製麺所・麺屋棣鄂による低加水の中太平打ち麺で、茹でたあと冷水で締め、手で握って余分な水気を落としてから昆布水にくぐらせるため、麺の表面には艶が出る。つけ汁は醤油味と塩味の二種類を用意し、塩は水出し昆布にドライトマトや椎茸、鶏肉、豚肉を合わせた清湯スープへ愛知県産のしじみを加えたもので、かえしには白出汁を用いて青ネギと刻み玉ねぎを添える。海苔は標準で付き、チャーシューは追加で頼める。価格はいずれも1,100円とされるが、内容や価格は変わることがあるため、訪問前に公式アカウントや電話で確認しておきたい。",
