        desc: "紅谷食堂の特徴は、時間帯によって役割を変える点にある。昼は定食やラーメンを出す食堂として近所の人の腹を満たし、夜になると酒とつまみを出す一杯飲める場に変わる。実際に訪れた客の記録によれば、昼どきから酒を楽しむ姿も見られたといい、時間の区切りに縛られない、地域に根づいた使われ方をしていることがうかがえる。観光地の飲食店のように一見客を意識した演出はなく、ホワイトボードに書かれた品書きを見ながら、その日ある料理を選ぶという、昔ながらの食堂の流儀が残る。一度で終わらず、仕事帰りに軽く一杯、休日の昼に一杯のラーメンというように、目的を変えて何度も足を運べる懐の広さが、この店を選ぶ理由になる。営業の詳細は変わることもあるため、訪れる前に電話などで確認しておくと安心だ。",
