        desc: "店の中心にあるのは、店主が目利きした魚介と、炭火であぶる焼き物だ。仕入れ先として三浦漁港や築地の名が挙がっており、その日に入った魚介をもとに刺し・焼き・煮といった形で仕立てるという。中でも繰り返し名前が挙がるのが刺身の盛り合わせで、案内サイトの多くが看板の一品として紹介しており、手頃な価格で出しているという説明も見られる。醤油と自家製のたれの両方で食べ比べられるという案内もあり、一皿で味の違いを楽しめる作りのようだ。焼き物では炭火を使った一皿も用意されており、脂の乗った魚や肉を炭の香りとともに味わえる。酒は日本酒に力を入れており、常時15〜20種ほどを揃えるとされる。銘柄の入れ替わりは早いようなので、その日の顔ぶれは実際に店で確認するのが早い。魚も酒も「今日ある分」を楽しむ店だと捉えておくとよいだろう。",
