        desc: "店主は吉祥寺や町田の繁盛店で腕を磨いたのち、地元である阿佐谷に戻って自分の店を構えたという経歴を持つ。修業先で培った魚の目利きと火入れの技術を、生まれ育った街に還元する形で始まった酒場ということになる。店内は「暖かみのある」と紹介されることが多く、身構えずに入れる気安さが特徴だ。値段を気にせず魚を選べる気安さを打ち出しており、懐具合を気にせず一杯だけ、あるいは数品つまんで長居する、という使い方のどちらも受け止めてくれる。カウンターで一人晩酌をする客と、座敷で仲間と盛り上がる客が同じ空間に同居できるのも、この店が長く通われる理由の一つだろう。日替わりの一品が用意されているため、同じ月に何度か通っても顔ぶれが変わり、飽きにくいという楽しみ方もできそうだ。地元に根を張って営業を続けている店だけに、常連として通う客を想定した気安い距離感が随所にあるようだ。",
