        desc: "メモアールがあるのは、長野電鉄長野線・市役所前駅から徒歩2〜3分ほどの一角で、昭和通りの地下連絡通路を使って地上に出るとすぐという、街の中心部らしい便のよい立地だ。長野市役所や周辺のオフィスに近く、行政の窓口に用がある日や、鶴賀エリアを歩いて回る合間に組み込みやすい。店の前には数台分の駐車スペースがあるとも伝えられ、車での立ち寄りにも対応できるようだが、台数は限られるため、時間帯によっては近隣のコインパーキングも視野に入れておきたい。長野駅からも歩いて向かえる距離にあり、駅前の混雑を避けて少し歩いた先で一息つきたいときの選択肢にもなる。街歩きの合間の一杯や、用事帰りの軽い食事に無理なく組み込める場所であり、雨や雪の日でも地下通路を使えば濡れずに向かえるのは、長野の冬を知る人にはありがたい利点だろう。",
