    sideArticles: [],
    quote: "長野市役所前、昭和通りの地下連絡通路を上がった先にひっそりと立つ、時代の空気をそのまま残す喫茶店。看板のナポリタンは、サラダとタバスコ、粉チーズを添えて出される昔ながらの一皿で、コーヒーやあんみつと合わせて、市役所への用事や鶴賀エリアの街歩きの合間にひとりで立ち寄る人の日常を、長年にわたって静かに支えてきた店です。",
    quoteCite: "マチノワ編集部",
    closing: "メモアールは、長野市役所への用事や鶴賀エリアの散策の合間に、肩の力を抜いて立ち寄れる喫茶店だ。ひとりでの一服なら30分ほど、サラダ付きナポリタンなどの軽食をとるなら1時間弱を見ておくと落ち着いて過ごせる。予算はコーヒー一杯からランチまで手頃な範囲とされるが、営業時間や定休日は情報源によって記載に差があり、クレジットカードが使えないとの情報もあるため、訪問前に026-228-6566へ電話で確認しておくと安心だ。最寄りは長野電鉄長野線・市役所前駅で、昭和通りの地下連絡通路を使えば雨や雪の日でも濡れずに歩いて向かえる。予約はおそらく不要な小さな喫茶店だが、団体での利用や混雑が気になる場合は事前の一報が確実だろう。観光の目玉として構えて訪れるというより、街での用事のついでに、あるいは昭和の空気に触れたいときにふらりと使うのが似合う一軒だ。",
