        desc: "霧笛の卓に並ぶのは、豚肉ともやしを炒め合わせた一皿や刺身、焼き物といった、居酒屋の基本形をきちんと押さえた料理だ。もやし炒めは湯気の立つ厚めの豚肉に、しゃきしゃきとした食感が残るもやしをたっぷり合わせ、皿の上で量感を主張する。華美な盛り付けを狙うのではなく、まず腹を満たし酒に合わせるという居酒屋本来の役割に忠実な料理立てで、メニューの幅は食事目的の客にも酒中心の客にも対応できる余地を残している。釧路港が近い土地柄、魚介を使う一皿が並ぶのも自然な流れといえるだろう。煮物や揚げ物なども含め、一皿ごとの量が控えめすぎない点は、小腹を満たしたい一人客にも、しっかり食べたい二人連れにも扱いやすい。具体的な品書きや仕入れ状況は日によって変わるため、訪問前に電話等で確認しておくと安心だ。",
