    sideArticles: [],
    quote: "霧笛という名は、海霧の街・釧路で船の航行を守るために鳴らされてきた音に由来する。釧路駅前を北へ抜ける北大通、焦げ茶色の外壁に白い看板を掲げるこの店も、大きく騒ぐことなく、焼きそばや刺身、焼き物を肴に、駅前の夜を一人でも連れとでも静かに受け止めてくれる。個室のない小さな造りだからこそ、身構えずに立ち寄れる居酒屋です。",
