    lede: "倉敷駅から浜町方面へ歩くと、美観地区の喧騒が少し遠のいていく。問屋街の名残を残す浜町2丁目は、観光客より地元の人が行き来する通りで、店構えも観光地価格でなく普段使いの顔をしている。その一角に「讃岐うどん 明月」がある。2010年の開業以来、かつおの出汁を軸にした讃岐うどんを出し続けてきた一軒で、浜町2丁目に根を張る地元の定番だ。麺は表面がつるりとしながら芯には噛み応えが残り、箸でつかんでもしっかりとした手応えがある。昼は10時半から営業するため、観光前の早い食事にも使え、夜は17時から21時まで開けているため、夕食の場としても機能する。うどんだけでなく、おでんや一品料理も揃い、軽く腰を落ち着ける選択肢もある。倉敷市内で何を食べるかを考えるとき、観光地の喧騒から少し外れた地元の定番を選びたいなら、この店は候補に挙がる一軒だ。",
