        desc: "かつおの出汁が効いたつゆは、甘みより出汁の輪郭を前に出したタイプだ。一口目から出汁の香りが立ち、飲み干しても重くならない仕上がりになっている。ぶっかけでも温うどんでも、つゆの主張がはっきりしているため、麺だけを啜るのでなく一口ごとに出汁の風味が感じられる。麺は表面がツルツルとしていながら、噛んだときに芯の弾力が残る仕上がりで、讃岐うどんらしいコシをしっかり持っている。倉敷風ぶっかけも提供しており、讃岐の出汁文化に倉敷ならではの食べ方が重なっている。メニューの価格帯は650円から1,180円程度で、肉うどん、鍋焼うどん、カツ丼セットなど選択肢が複数ある。期間限定のおろし醤油うどんも提供することがあり、時期によって内容が変わるため、気になるメニューがある場合は来店前に電話か公式SNSで最新情報を確かめておくと確実だ。どのメニューを選んでも出汁の存在感が軸になっており、うどんを「つゆごと楽しむ」食体験として整っている。倉敷市内でうどんの出汁文化を探すなら、この一軒は外せない選択肢になる。",
