    title: "倉敷駅から7分、旬食材と和のテイストが交わるイタリアンバル。Legameで過ごす、夜の食事の時間",
    titleHTML: "倉敷駅から7分、旬食材と和のテイストが交わる<br /><em>イタリアンバル Legame</em>で過ごす、夜の食事の時間",
