        area: "倉敷市阿知",
        purpose: "この店の料理スタイルの核を伝え、食事目的の来店理由を作る",
        desc: "Legameの料理の中心にあるのは、イタリア料理の基本的な枠組みに、四季の旬食材と和のテイストを掛け合わせた独自のスタイルだ。定番のイタリアンから逸脱しすぎず、日本らしい食材の使い方を随所に混ぜ込む塩梅が、この店の料理を「どこにでもあるイタリアン」と区別するポイントになっている。マルゲリータはチーズとトマトの基本バランスに忠実でありながら、生地の焼き方に独自性が感じられる一枚だ。パスタは870円〜1,250円程度の価格帯で、にんにくとモッツァレラを合わせたトマトソース系のほか、季節の素材を使ったメニューが並ぶ。旬食材がどのように使われているかは時期のメニューによって異なるが、食材の選び方に季節感が反映されている点が、定番のイタリアンとの違いとして感じられるところだ。和のテイストは仰々しく主張するのではなく、素材や調理のさりげない選択として料理に馴染んでいる。コース料理も用意されており、記念日や会食の場でじっくり食事を楽しむ使い方もできる。コース料金の目安は5,000円（税込）程度とされているが、内容・価格は変わることがあるため、利用前に店へ問い合わせておくと確実だ。季節ごとに変わる食材の使い方は、同じ店に繰り返し来たくなる理由にもなっている。",
