        purpose: "バルとして気軽に使える理由を前菜ラインナップで具体的に伝える",
        desc: "バルとして使いやすい理由のひとつは、前菜の選択肢の充実にある。生ハムとトマトのサラダ、トマトとチーズのアヒージョなど、テーブルに数品並べながらワインを開ける組み立てがしやすい。アヒージョはオリーブオイルにトマトとチーズを合わせた仕上がりで、パンをつけながら食べるスタイルが料理の味をより引き立てる。生ハムを使ったサラダは最初の一皿として頼みやすく、テーブルに出た瞬間から食事の雰囲気が立ち上がってくる。前菜を2〜3品並べてから、メインのパスタやピッツァに移る順番で食事を組み立てると、バルらしい時間の流れができる。ワインとシャンパンが充実しているとのことで、食事の流れに合わせてグラスを進める楽しみ方もこの店の持ち味だ。「ちゃんとした料理で少し飲みたい」というシーンに、前菜の引き出しが豊富な点は正直頼りになる。デートでの利用でも、前菜を一品共有しながら話す時間がそのまま食事の入口になる。ドリンクのラストオーダーは22時30分のため、しっかりペースを楽しむなら20時台に入るのが理想的だ。メニューや価格は時期で動くので、訪れる前に電話や公式SNSで確認を。",
