        desc: "Legameでの食事の骨格を作るのは、ピッツァとパスタだ。マルゲリータはピッツァの基本を押さえた一枚で、チーズとトマトとバジルのバランスを確かめられる。生地の焼き加減に独自のこだわりが感じられ、定番メニューであることの安心感と、この店ならではの仕上がりを同時に味わえる。パスタはソースのバリエーションが複数あり、にんにくとモッツァレラを使ったトマトソース系のほか、クリームや魚介を使ったメニューも揃っているとのことだ。価格帯は870円〜1,250円程度で、単品で頼んでも財布への負担が少ない。2人でピッツァ一枚とパスタ一皿をシェアするという頼み方は、テーブルに適度な量が出てきてちょうどいい。前菜を一品挟んでから、ピッツァとパスタをシェアしながらドリンクを飲む流れは、バルとしての夜の使い方として収まりがいい。デザートにはカタラーナが用意されており、濃厚なクリームの甘みで食後を締めくくる選択肢がある。特定の料理を目当てに来店する場合は、メニュー変更に備えて事前に店（090-2803-2026）へ電話で確認しておくと確実だ。",
