    titleHTML: "日光今市、道の駅に宿る手打ち蕎麦。<br><em>きすげの郷 蕎粋庵</em>で知る、地粉と名水の一杯",
    subtitle: "栃木・日光市今市 / 手打ちそば / ランチ・日光観光の昼食",
    lede: "今市という地名は、日光へ向かう旧街道の宿場として長く機能してきた場所だ。東武日光線の下今市駅とJR日光線の今市駅がほぼ並んで位置し、観光客が乗り換えの拠点として使う街でもある。その今市の市街地に、全国的にも珍しい形態の施設がある——道の駅「日光街道ニコニコ本陣」だ。郊外の幹線道路沿いに作られるのが一般的な道の駅だが、ここは駅から徒歩5分という住宅・商業エリアの中に立地している。その建物の中に、きすげの郷 蕎粋庵はある。日光産のそば粉と今市に湧く名水を合わせ、毎日店内で打つ二八手打ちそばを提供する蕎麦処だ。炭を練り込んだオリジナルの炭そば、栃木の郷土食として知られるちたけを使った蕎麦、葉わさびを乗せた一杯など、日光という土地の食材と文化に根ざしたメニューが並ぶ。観光客から地元の昼食利用まで、今市という街の重層的な顔がここに集まっている。",
