        desc: "蕎粋庵の蕎麦は、日光産のそば粉と今市の名水を使った二八手打ちだ。そば粉8割、つなぎ2割の二八は手打ちの中でも標準的な配合だが、素材の質がそのまま味に直結する。地元産のそば粉を自家製粉しているという点が、他の蕎麦処との差につながっている。日光は気候が冷涼で、そば粉の産地として条件が整っている。製粉したての粉で打つそばは、乾燥させた粉を仕入れて打つものとは香りが違う。名水を使うのも、水がそばのつなぎに与える影響を知ってのことだ。今市には古くから湧水が豊富で、水の良さが地元の食文化を形成してきた歴史がある。この店の蕎麦は「コシが強い」という評が複数の媒体で確認できる。腰の強さとつゆの旨みが合わさった一杯が、この店の軸だ。蕎麦は量が品切れになり次第終了するため、食べることを目的に来るなら昼の早い時間に入るのが確実だ。日光という観光地が近いため午後になると混み合うことがあり、品切れのリスクも高まる。「この日光産の一杯」を目当てに来るなら、開店直後の11時台を狙う方が安心だ。",
