    subtitle: "秋田市新屋 / 定食・食堂 / ランチ・夕食",
    lede: "新屋豊町という地名を、秋田市外の人はほとんど聞いたことがないかもしれない。JR羽越本線の新屋駅から歩ける距離に、住宅と小さな工場が混在する一角がある。その奥まった場所に「秋桜（こすもす）」の看板が立っている。ガラス戸の向こうに見えるのは、黒板に書かれた今日のメニューと、カウンターに腰を落ち着けた常連の後ろ姿だ。開店時間になると、近隣の職場で働く人たちが流れ込んでくる。ランチタイムはすぐに席が埋まり、定食の皿が次々と運ばれる。ホルモンセットにカツオの刺身が付いてくる独特の組み合わせ、ボリューム満点の味噌チャンポン、サバ味噌煮とから揚げのセット——どれも「ごはんの量がすごい」「コスパが高い」という声が口コミに繰り返し登場する。新屋という街に昔からある食堂として、秋桜はこの場所に根付いてきた。観光で訪れるタイプの店ではないが、秋田市で「飾らない地域の定食屋」を知っておきたいなら、この一軒の名前は記憶に値する。",
