        area: "秋田市新屋",
        purpose: "他の食堂にはない個性的なメニュー構成を伝える",
        desc: "秋桜の口コミで繰り返し取り上げられるメニューのひとつが「ホルモンセット」だ。ホルモンの炒め物にカツオの刺身が一緒に付いてくるという、定食屋では珍しい組み合わせが特徴で、初めて見た人は意外性に驚く。焼き系のおかずと刺身が同じセットに収まっているのは、秋田という土地柄と、この店の仕入れルートや調理の幅広さを反映している。秋田は内陸部でも鮮魚の流通が発達しており、カツオのタタキや刺身は地元の食卓に馴染みが深い。定食屋で刺身系が提供されること自体は珍しくないが、ホルモンとカツオの組み合わせをひとつのセットとして成立させているのは、この店のメニュー設計の個性だ。黒板を見て何を頼めばいいかわからない場合、ホルモンセットを選んでみるのが秋桜らしさを知る近道になる。味噌チャンポンも常連に支持されているメニューで、具材の多さとスープのコクが特徴として挙げられている。サバ味噌煮とから揚げのセットのように、複数のおかずをまとめてひとつの定食にする構成も、量を食べたい来客の需要にはまる。どのメニューも「想像以上の量」という点では共通しており、食べ切れるかどうかを一瞬考えながら注文する人もいる。メニューの実際の内容と価格は変わることがあるため、内容は来店前に店へ確かめるのが確実だ。",
