    subtitle: "中華料理・下関駅周辺・ランチ〜ディナー宴会",
    lede: "下関の市街地を走る国道9号は、関門海峡に向かって緩やかに傾斜し、唐戸方面への人の流れを作り続けている。下関駅から14分ほど歩き、入江交差点で右に折れると、岬之町16-11番地に「太平楽本店」がある。窓から見えるのは静かな通りで、看板を知らなければ通り過ぎてしまいそうな構えだ。しかしこの一軒、昼から常連が顔を出し、夜には焼酎片手に仕事上がりの客が集まる——下関の日常に染み込んだ中華料理店として、この場所に根を張り続けている。四川料理をベースにしながら、ラーメン・丼・飲茶まで揃え、コース料理にも対応する守備範囲の広さが特徴だ。麻婆豆腐・回鍋肉といった定番から、北京ダックのような本格的な一品まで出る店を、ランチ千円以内で使える。格式を求める客にも、気軽な昼食を探す客にも応じられる懐を持ち、地元の生活に組み込まれてきた一軒として、下関を訪れる人にも知っておいてほしい場所だ。",
