        desc: "大翔のメニューには、定番の醤油・味噌・いわし醤油ラーメンの横に、創作系のラインが育ってきた。代表的なものがイカスミを使ったシリーズで、スープベースにイカスミペーストを溶かすことで色と深みを加えている。イカスミ醤油ラーメンでは、ニンニクの香ばしさがアクセントとして機能する。イカスミ焼きラーメンは、平打ちストレートの太麺をニンニク・キャベツ・タマネギと一緒に炒め、醤油ダレとイカスミで仕上げた一品で、「ラーメン」と「炒め」の中間にあるような食感がある。季節限定のメニューも定期的にラインナップされていて、訪れるたびに定番の隣に何か新しいものが加わっている可能性がある。同じ店に何度も来ている人が毎回メニュー表を確認するのはそのためだ。黒いスープのインパクトは食卓での話題にもなりやすく、二人以上で来て一つ試してみるのも選択肢の一つだ。期間限定メニューの有無は来店前に電話か公式SNSで確認すると確実だ。",
