    lede: "越前東郷は、福井市の中心部から南西に離れた小さな地区だ。冷たく清らかな山の水が流れ込む水田が広がるこのエリアは、コシヒカリの産地として農家が代々大切に守ってきた土地でもある。JR越前東郷駅の改札を出て左へ歩くと、100メートルほどで毘沙門寿司の看板が目に入る。1977年の開業以来、この店は「米どころ東郷の自家米で寿司を握る」という一点を変えていない。有機肥料と減農薬栽培による特別栽培米コシヒカリを自分たちで育て、新米は土蔵で1年以上寝かせてから厨房に入れる。余分な水分が抜けた米は炊き上がりの表情が変わり、それを寿司飯に仕立てたときの仕上がりに差が出る。この米を使ったバッテラ風さば棒寿しが、近年は福井県外からも客を呼ぶ名物になった。地域の食堂として47年。東郷の人たちの日常をそっと支えてきた一軒に、今では全国から人が向かっている。",
