    lede: "下関・入江町は、JR下関駅から歩けば15分ほど、バスを使えば「入江口」停留所からほんの1分の距離にある。観光客が多く集まる唐戸エリアから少し外れた、どこかのんびりとした通りの一角に、帽子の緑の看板が目に入る。「MAKO CHANNEL」——2022年9月後半にオープンしたミュージック＆ダイニングバーだ。東京から地元にUターンした店主・MAKOさんが、自ら運営する農場「MAKO FARM」で育てた有機野菜と、唐戸市場から直接仕入れる鮮魚を使い、化学調味料を使わない手作り料理を提供している。下関産オーガニック米で炊く土鍋ごはん、有機にんじんを主役にしたメニュー群、季節のクラフトビール。大人の食事とドリンクが、流れる音楽とともにある夜の時間——入江町に、そんな空間が静かに根付いている。",
    date: "2026-08-08",
    reading: "",
    author: "マチノワ編集部",
