        area: "下関市入江町",
        purpose: "他店と違う特徴、この店ならではの食体験を伝える",
        desc: "MAKO CHANNELのメニューの中で特に存在感があるのは、関門タコを使った料理と、土鍋ごはんだ。関門海峡産のタコはカルパッチョやアヒージョに仕立てられ、素材の柔らかさと旨味をそのまま活かした調理になっている。一方、土鍋ごはんは下関産オーガニック米を注文が入ってから炊く仕様で、炊きたての状態でテーブルに届く。おみそ汁と香の物がつく「土鍋ごはんセット」として頼めば、食事の主軸になる。ダイニングバーでありながら、ちゃんとした「ご飯もの」が中心にある——これが、MAKO CHANNELを単なる飲み屋ではなく、食事の場として選べる理由のひとつだ。アジフライには下関産のアジを使い、えびの素揚げも下関産だ。地元食材を積み上げたメニュー構成は、「どこで採れたかを知っている食材しか出さない」という方針から来ている。日替わりのお造り盛合わせには、その日の唐戸市場の仕入れ状況が反映される。何を頼むか迷ったとき、まず土鍋ごはんセットと関門タコの一品を頼んでおけば、MAKO CHANNELの軸が見えてくる。",
