        cuisine: "メニュー・ドリンク",
        area: "下関市入江町",
        purpose: "具体的なメニューとドリンクラインナップ、食体験の幅を伝える",
        desc: "「下関一のにんじん推し店」と言われるくらい、MAKO CHANNELはにんじんにこだわる。MAKO FARMで育てる無農薬にんじんは、スティック・ジュース・ポタージュ・ケーキとさまざまな形で料理に登場する。「有機にんじんのポタージュ」は、余計な素材を加えずにんじんの甘みを引き出したスープで、食事の入口として注文する人が多い。締めに頼む「有機にんじんのケーキ」は、甘さを抑えた食べやすい仕上がりだ。ドリンクは季節のクラフトビールをはじめ、焼酎・ワイン・カクテル・日本酒・ウイスキーと幅広い。食事メニューでは、有機野菜たっぷりのマコカレーや、自家製ベーコンを使ったキャベツ炒め、但馬合鴨コロッケといった個性的な一品が並ぶ。固定メニューと日替わりが混在する構成のため、同じ日に同じ料理が揃うとは限らない。それがこの店の面白さでもある。ナッツやドライフルーツのような軽い一品から、关门タコときのこのアヒージョまで、飲みながらつまむものを少しずつ頼んでいく楽しみ方が自然に合う。",
