        area: "下関市入江町",
        purpose: "店内の雰囲気・席構成・誰と行きやすいかを伝える",
        desc: "MAKO CHANNELの店内は、帽子の緑の看板が目印の入口を入ると、音楽が流れる落ち着いた空間が広がる。席数は24席で、ソロ飲みからグループまで対応した構成だ。個室も用意されており、少人数での会食や女子会、打ち合わせ帰りの一杯にも使える。店の特徴として目立つのは、半地下スペースだ。ここではライブイベントが開催されることがあり、店主MAKOさん自身がミュージシャンでもある背景から、音楽と食事が一体になった時間を提供している。ライブのある日はあらかじめ公式SNSで告知されるため、音楽目当てで来店する客も少なくない。普段の夜は大きな音量ではなく、BGMとして流れる音楽の中で食事を楽しむスタイルだ。都会的でおしゃれな空間と評されることが多く、カジュアルすぎず堅苦しすぎない、ちょうどいいトーンの店だ。一人でカウンターに座って、好みの日本酒とにんじんのポタージュを頼む使い方も自然に成立する。大きな宴会には向かないが、2〜4人での食事や仕事帰りの一人飲みには、かなり使い勝手がいい。貸切予約にも対応している。",
