        desc: "住所は山口県下関市入江町2-10 1F。JR山陽本線の下関駅から歩くと約15分だが、サンデン交通のバスを使えば「入江口」停留所から徒歩1分とアクセスが大幅に短縮できる。電車で下関に来た旅行者なら、バスを選ぶのが現実的だ。下関は唐戸市場・亀山八幡宮・関門トンネル人道・関門橋のある和布刈公園といった観光スポットが複数あり、夕方まで歩き回ったあとの夜に立ち寄る店を探すと、このエリアが候補に入る。唐戸市場は翌朝に行くこともできるため、前夜をMAKO CHANNELで過ごし、翌朝に唐戸へ行くという旅程の組み方もある。営業は夜の開始を基本とするが、日曜・祝日は昼飲みに対応した時間帯から開けることもある。月曜定休。駐車場はないため、バスでのアクセスが便利だ。予約は電話で受け付けており、個室や貸切利用を希望する場合は事前に連絡しておきたい。下関観光の拠点として宿をとった夜に、食事の場として組み込む使い方が自然に合う一軒だ。来店前に電話（083-242-4240）か公式SNSで最新情報を確かめておくと確実だ。",
