    quoteCite: "マチノワ編集部",
    closing: "入江口のバス停を降り、帽子の緑の看板を探して1分歩く——その短い道のりが、MAKO CHANNELの入口になっている。夜の開店は17〜18時台が目安で、ラストオーダーは23時頃。日曜・祝日は昼から開けることもあり、唐戸市場や関門エリアを午前中に歩いた後、夕方から立ち寄る旅程にも組み込める。一人でカウンターに座り、土鍋ごはんセットとにんじんのポタージュを頼むだけで、一定の満足感が得られる使い方になる。少人数なら個室を使うと落ち着いて食事ができる。ライブのある日は事前に公式SNS（@mako_channel55）で確認しておくと、目的を持って訪れられる。月曜は定休で、駐車場はないためバスでのアクセスが便利だ。食事とドリンクを組み合わせると自然に2時間は過ごせる密度があり、一軒に腰を落ち着けて夜を過ごすスタイルに合っている。どんな食材が届いているか、その日の日替わりを確認しながら注文を組み立てていくのが、MAKO CHANNELとの付き合い方だ。メニュー・価格・営業時間は変更になることがあるため、来店前に電話（083-242-4240）か公式情報で確認しておきたい。",
