    closing: "スープが終われば、その日の麺や せん崎も終わる。15時より前に閉まることもある。この店を確実に経験するには、「昼に動ける日を先に確保する」ことが出発点になる。車があれば郡山市内からのアクセスは難しくない。駐車場が整っているため、家族連れや複数人での来訪でも止める場所の心配は少ない。郡山富田駅から歩くことも不可能ではないが、約1.7kmの道のりは夏の昼間には負担になることがある。着席したら、醤油か塩か、太麺か細麺かを選ぶだけで注文は動き出す。地鶏醤油（900円）と地鶏塩（900円）はどちらも同価格で、飲み比べには2回の来訪が必要だ。全部入り（1,300円）なら具材を一通り確かめられる。和え玉（300円）を加えれば、丼一杯で2種類の麺体験ができる。子連れなら座敷席とお子様らぁ麺（400円）を組み合わせると、席の広さと価格の両面で安心して座れる。郡山市内で昼に一杯、と決めた日に向かう先として、この店名を手元に持っておきたい。営業時間・定休日・価格・支払い方法は変更されることがある。来店前にInstagram（@menya__senzaki）か電話（090-8237-4521）で最新情報を確認してから動くことを勧める。",
