        desc: "参道酒場 鶏居の看板に「鶏」の字が入っているのは伊達ではない。店が最も前面に押し出すのが、「名物！特大つくね」と「手羽先唐揚げ」の二品だ。特大つくねは、タレ卵黄・タレチーズ・塩わさびの3バリエーションで展開されており、100gあたり396円という設定。つくねの大きさを「特大」と銘打つ以上、テーブルに届いたときの存在感は一般的な居酒屋の串物とは一線を画す。3種のトッピングのどれを選ぶかによって同じつくねが違う顔を見せるため、グループで一種ずつ頼んで食べ比べる使い方もできる。手羽先唐揚げは、特製スパイス・秘伝のタレの2スタイルで、6本520円。揚げ物の中でも手羽先は仕込みの影響が味に直結する部位で、この店が「特製」「秘伝」という言葉を使う背景には、それだけの仕込みへのこだわりがある。鶏料理を専門にする店として、まずこの二品を軸にオーダーを組み立てるのが、この店の使い方の基本になる。メニューや価格は時期によって変わることがあるため、来店前に最新情報を確かめておきたい。",
