        desc: "参道酒場 鶏居は焼鳥・串料理が看板だが、メニューはそこで止まらない。「選べるスープのちりとり鍋」は小（約2人前）1,408円・大（約4人前）2,728円で設定されており、グループでの食事の中盤から後半にかけて頼む一品として機能する。スープの種類を選べる仕立てになっているため、テーブルの好みに合わせて調整できる。ちりとり鍋は肉と野菜を一度に食べられる点で宴会の後半向きの一品で、串を食べ終えた後の「締め」の動線を自然に生み出す。さらに、日本海に近い立地を活かした上越の地元海鮮メニューも揃えている。上越は直江津港を抱える漁港の街で、日本海からの新鮮な魚介が入る。焼鳥と海鮮、そして鍋が一つのテーブルで揃う構成は、長い時間をかけて過ごす居酒屋使いに向いている。具体的なメニュー内容は時期で変わることがあるため、来店前に店へ問い合わせておくと安心だ。",
