        desc: "参道酒場 鶏居の住所は新潟県上越市中央1-5-19。JR信越本線の直江津駅北口からおよそ徒歩3分という距離感は、上越市内の居酒屋の中では駅近の部類に入る。駅を出てから3分で着く店は、移動時間のことを考えずに「じゃあここにしよう」と決められる手軽さがある。営業時間は月曜から土曜の17:30〜翌2:00（ラストオーダー1:30）で、定休日は日曜日。深夜2時まで開いていることは、上越エリアでは特筆に値する。終電後でも営業しており、夜遅くまで続く飲み会の場として機能する。一次会の会場としても、二軒目・三軒目の選択肢としても、時間帯を問わずに収まりがいい。直江津は上越市の中でも日本海沿いの港エリアで、えちごトキめき鉄道と信越本線の乗り換え駅でもある。上越観光の拠点として直江津を選んだ場合、夜の食事の選択肢としてこの店を動線に組み込むことができる。営業時間・定休日は変更されることがあるため、事前に店へ問い合わせておくと確実だ。",
