    lede: "延岡市の熊野江町は、宮崎県の海岸線に位置する場所だ。町の名に「熊野江」とあるように、日向灘に面した海沿いの集落である。こうした立地だからこそ、朝の競り場から漁師たちが持ち込む新鮮な海鮮が手に入る。そんな海の近さを直結させた形で営業する店が「旬肴」だ。この店では、毎日異なる海の幸が握られ、衣をかぶられ、丼に盛られる。営業時間は火曜から日曜の10時から14時。昼間だけという限定された時間帯が、この店の一皿を特別にしている。朝から昼間にかけて、地元の客たちが通う理由は、その時間帯に熱々の天ぷらが揚がり、季節ごとの丼が完成するからだ。素材の季節感を最も短い流れで表現する、そんな一軒の営業の仕組みを見てみたい。",
