        desc: "旬肴の顔となるのは「地どれ海幸丼」¥1600だ。「地どれ」とは、その地域で採れた、という意味。つまり、延岡から日向灘で採れた、その日もしくは前日の朝に船から上がった海の幸が、そのまま丼として盛られるということだ。こうした直結の仕組みが成り立つ背景には、熊野江という漁業地帯の立地と、漁師たちとの信頼関係がある。大量仕入れの外食チェーン店ではなく、小規模な一軒の食堂だからこそ、ある特定の漁師から「今日は良いネタが上がった」という連絡を受け、その時季の旬の素材を使った丼を創作できるのだ。この丼に乗っているのは、毎日違う魚かもしれない。あるいは同じ魚でも、前の週より脂が乗っているかもしれない。季節によって、色が違うかもしれない。つまり、旬肴の地どれ海幸丼は「今この瞬間」を食べるものであり、昨日と同じ、明日と同じではない一品だということだ。漁業地帯に根ざした食堂だからこそ可能な、季節感の最短距離での表現である。朝の仕入れが、昼の丼になる。その速さが、他の場所では味わえない新鮮さを生み出している。",
