        purpose: "揚げたての食感がもたらす食事の満足感を知る",
        desc: "「天ぷら定食」¥1200は、この店のもう一つの柱だ。定食というカテゴリは、日本の昼食文化では最も基本的なフォーマットだ。天ぷら定食と言えば、ご飯、揚げたての天ぷら、汁物、漬物という組み合わせが標準的である。しかし、この「揚げたて」というのが実現するのは、意外と難しい。回転率が低い店では、作り置きされた冷めた天ぷらが出される。あるいは時間が経った衣がしなびているということも珍しくない。旬肴の天ぷら定食が異なるのは、昼間の限定営業時間というスケジュールの中で、客の来店に合わせて揚げるというシンプルな事実にある。朝の10時の来店者のために新しく揚げ、その人が食べ終わる頃には次の客のために揚げ始める。こうした緊張感のある営業が、毎回の天ぷらを「今これから食べるものを揚げています」という状態に保つ。素材に関しても、漁師からの仕入れと同じで、海のものと山のものが日替わりで入ってくる。季節の野菜、地元産の野菜、そして時には珍しい海産物の天ぷらも。定食という形だからこそ、主役の天ぷら以外の要素（ご飯、汁、漬物）の質も丁寧に組み立てられている。この一皿を食べると、「定食」という日本の食事の作法が、単なる組み合わせではなく、緻密に計算された構成だということが理解できる。",
