        desc: "旬肴のメニューは、非常に限定的だ。地どれ海幸丼、天ぷら定食、天丼¥900、おまかせ定食¥900という4つの選択肢がメインで、その他にも小メニューがあるかもしれないが、基本的には「この店で何を食べるのか」という判断は、非常に簡単だということだ。これは、実は非常に高度な営業設計である。なぜなら、現代の飲食店は選択肢の多さで客を魅了しようとするからだ。100品以上のメニュー、シーズンごとの新作、オリジナルの組み合わせ。こうした複雑さに惹かれる客もいる。しかし、旬肴は逆だ。シンプルだからこそ、毎日通っても飽きない。なぜなら、同じ天ぷら定食でも、素材は毎日違うからだ。選択肢の複雑さで対応するのではなく、素材の季節感で客を満足させている。また、メニューが少ないということは、作り手にとって「一つ一つの料理に集中できる」ということでもある。4つのメニューを完璧に仕上げることは、50のメニューを平均的に作るより、はるかに難しい。その「難しさへの向き合い方」が、客の一皿に現れている。訪れる前に電話で本日のメニューを確認することで、さらに最適な来店タイミングが見えてくる。わずかな選択肢の中で、何を選ぶか。その判断は、実は素材を選ぶことと同義なのだ。",
