        desc: "営業時間は火曜から日曜の10時から14時。朝10時というのは、朝食を終えて、昼食にはまだ早いという微妙な時間帯だ。しかし、この時間帯こそが、朝獲れの海鮮を使った食堂の理想的な営業時間である。漁師が港で競りを済ませ、仕入れた海産物を持ってくるのは朝の9時、10時。それを仕込んで、メニューとして提供開始するのが10時という設定は、つまり「その日の朝の素材で、その日の朝の営業を始める」という意図が見えている。昼の14時で営業を終了するのも、意図的だ。夜間営業をしていない理由は、単純に「昼間に限定することで、毎回の素材と調理を高い水準で保つ」という経営判断なのだろう。この4時間という限定性が、客側にも影響を与える。いつでも来られるわけではないから、この店に行くときは「その時間を避けられない」という優先順位が生まれる。つまり、旬肴を選ぶ日は、「何をどこで食べるか」ではなく、「10時から14時のこの時間に来られるか」という日程調整から始まる。この逆算の関係性が、客の来店をより意識的なものにしている。営業時間や定休日は変わる可能性があるため、訪問前に電話（0982-43-0020）での確認をおすすめしたい。",
