        desc: "住所は宮崎県延岡市熊野江町2532-1。熊野江町は、延岡市の海岸線に位置する地域である。延岡駅からは、海方向へ向かう形で車で15分から20分ほどかかる。車でのアクセスが基本になる場所だ。最寄りのバス停も限定的である可能性があるため、事前に交通手段を確認してから訪問するのが確実だ。この立地は、実は旬肴という店にとって重要な要素である。市街地から少し外れた、海沿いのこの場所だからこそ、漁師たちが直接乗り込んできて、その日の朝獲れの海産物を持ってくるのだ。逆に言えば、わざわざこの場所まで来る客は、「目的地として旬肴を選んだ」という意図を持っている。延岡市内の海の近さを知りたい、朝獲れの海鮮を食べたい、そういう意思のある客だけが、この場所に辿り着く。市街地から少し離れているという事実が、客の来店を「なんとなく通りかかった」ではなく、「目的を持って訪れた」という質に変えている。また、この立地は延岡の他の観光スポット、例えば日向灘の海沿いドライブ、島野浦などの近隣観光地との組み合わせで活かせる。昼食を旬肴で食べてから、海沿いを散策する、という使い方も可能だ。来店の際は、営業状況を確認する電話（0982-43-0020）をする際に、アクセスについても相談するといっそう確実だ。",
