    lede: "福島市の郊外に位置する南向台という落ち着いた高台に、控えめな暖簾で佇む「旬菜美味 南風亭」。この店を訪れるには、電話で予約を入れることが必須だ。訪問者の期待値をあらかじめ引き上げる「完全予約制」という構えが、この一軒のポリシーを物語っている。仙台や宮崎から直接仕入れた新鮮な魚介と、その季節に最も良い素材を活かした創作懐石が中心になる。季節ごとに「特選コース」は全面リニューアルされ、年に4〜5回ほど異なるテーマで展開する。完全個室という空間づくりは、家族の大事な集まり、記念日のディナー、ビジネス接待という異なる用途を、同じ店内で成立させている。",
