        desc: "懐石というと格式高い店というイメージを持つ人も多いが、この店は「創作」という言葉が示す通り、伝統的な懐石の枠を柔軟に広げている。仙台の港から直送される本マグロの中トロ、宮崎の豊かな日差しのなかで育った魚介類は、素材の力を引き出す調理で供される。春ならば新わかめや筍、夏は夏野菜と鮮魚の組み合わせ、秋は松茸や栗といった山の幸、冬は白魚や蟹といった冬の味覚が中心になる。一品一品に手間をかけた調理が、単なる「豪華な一皿」ではなく、その季節ならではの香りや味わいの重層性を生み出している。コース料理であるため、食べる順序も計算されており、前菜からはじまり向付・煮物・焼き物・揚げ物・ご飯と、食事としての完結性がある。個室という空間で、料理人の技を身近に感じながら、季節の美味をかみしめていく。そういう時間の過ごし方が、この店の基本形になっている。懐石の伝統と創作の自由度のバランスが、訪れる人の「食べることへの期待」を、自然と満たしていくのだ。",
