        desc: "基本となるコース料理があるなかで、この店の大きな特徴が「特選コース」の存在だ。年に4〜5回、季節が変わるたびに、コース全体の構成がリニューアルされる。春は春キャベツや新緑の野菜、春の獣肉を組み合わせたテーマに、夏は冷たい一品や夏野菜の涼しさを引き出すテーマに、秋は狩猟の季節の野兎や鴨といった秋の獣肉と山菜のコンビネーション、冬は温かさと豪華さを両立させたテーマ構成になる。毎シーズン異なる「顔」を持つコースが用意されるため、複数回訪れるリピーターにとっても新しい発見がある。予約を入れるときに「いつごろに訪問したいか」を伝えることで、その時期の特選コースを確保してもらうことができる。家族の記念日に合わせて「その月の特選コース」を狙って予約する、という使い方もできる。季節感を大事にする懐石文化の中でも、この店はシーズンごとのリニューアルを重視する姿勢を持っており、それが「何度も通いたくなる理由」になっている。食べログなどでは59枚の写真が公開されており、その豊富な料理バリエーションが、店への期待感を高める前提になっている。通算で何度訪れても、新しいテーマに出会える。そういう継続的な魅力が、懐石文化の根底にはある。",
