    lede: "愛知県安城市は、名古屋から南東へ電車で30分ほど。かつて繊維産業で栄えたこの町は、今も刈谷・豊田といった工業都市と隣り合い、ものづくりの顔を持ちながらも、どこか落ち着きが保たれている。名鉄本線新安城駅を降りて周辺を歩くと、昔からの商店と新しい飲食店が混在する商業地帯が目に入る。そうした町の様子の中にぽつんと佇む『イタリア料理 らぱん』は、安城という土地を知る人ほど、訪れる理由が明確になる店だ。三河湾で採れた新鮮な地魚、安城で育った牛肉を、イタリアンの手法で調理する。地元の食材の真価を引き出すことに徹した、そんな一軒である。",
